-- Batumi & Adjara — 12 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Black Sea coast & subtropical hills',
  summary       = 'Georgia''s subtropical Black Sea coast: a Belle-Epoque resort city of Art Nouveau facades, a seven-kilometer seaside boulevard and neon nightlife, backed by the green, rain-soaked hills of Adjara. Batumi itself delivers beaches, a cliffside botanical garden and a genuinely distinct cuisine — Adjaruli khachapuri, the boat-shaped cheese bread topped with egg and butter, originates here — while a short drive inland or south along the coast reaches a Roman-era fortress, a border-village beach, and a valley of waterfalls and stone arch bridges. It''s a full multi-day base in its own right, not just a coastal add-on to the rest of Georgia.',
  when_to_go    = 'June through September is peak season: hot, often above 30C, humid, and the boulevard and beaches get genuinely crowded, especially in August. Late spring (May) and early autumn (September-October) are quieter and more comfortable for walking and sightseeing, with the sea still warm enough to swim into October. Adjara has Georgia''s highest rainfall year-round, heaviest in the inland hills — pack a rain layer even for a summer visit, and keep at least one indoor backup (the art museum, a covered restaurant) in your plan regardless of season.',
  getting_there = 'Batumi is roughly 350km from Tbilisi. Driving takes about 5-6 hours via the Tbilisi-Senaki-Batumi highway; the daily direct train takes around 5-6 hours; domestic flights (about an hour in the air) connect Tbilisi and Batumi but add airport time on both ends, so total door-to-door time often lands close to the train. Frequent marshrutkas (minibuses) run from Tbilisi''s Didube station. Within the region, Gonio and Sarpi are a short drive south along the coast road; Mtirala, Makhuntseti and the Tamar Bridge are 30-50 minutes inland up the Acharistsqali valley and need a car or organized tour, since public transport up the valley is thin.',
  base_towns    = 'Batumi is the obvious base — hotels and guesthouses across every budget, and everything on the boulevard and in the old town is walkable. Kobuleti, about 20km north, is a cheaper, quieter beach-town alternative with easy access back into Batumi and toward Mtirala National Park.'
WHERE id = 'batumi-adjara';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('batumi-adjara-boulevard', 'batumi-adjara', 'Batumi Boulevard', 'Seven kilometers of palms, cycle paths and Black Sea views strung along the entire city front.', 'Batumi Boulevard runs the length of the city along the seafront, combining the older 19th-century "Old Boulevard" near the port with a modern 1200-meter extension built in 2009. Palm-lined paths carry cyclists, joggers and evening strollers past fountains, open-air cafes, the Ferris wheel and Alphabet Tower, and long stretches of pebble beach. After dark the boulevard''s dancing fountains run in bursts roughly every hour between 21:00 and 02:00, and the whole strip lights up with the city''s neon skyline. It''s the connective spine of a Batumi visit — you''ll pass through parts of it multiple times rather than visiting it once.', 'Free to walk; rental bikes and electric scooters are available at stands along the route if you want to cover more ground. Midday sun has little shade for long stretches, so early morning or evening is more comfortable in summer.', 'Early morning or after sunset', 90, '1.5 hr', NULL, NULL, 'Free', 'Batumi', 41.653612, 41.634536, 'Playgrounds, wide flat paths for scooters, and ice cream stalls the whole way — an easy win with kids of any age.', false, ARRAY['walk', 'scenic', 'kids']::TEXT[], 1, NULL, NULL),
  ('batumi-adjara-old-town-piazza', 'batumi-adjara', 'Batumi Old Town & Piazza Square', 'Cobbled lanes and Art Nouveau facades around a marble mosaic square at the heart of old Batumi.', 'Piazza Square sits a few streets back from the boulevard, its centerpiece a large marble mosaic floor surrounded by a ring of buildings styled after different European architectural traditions. From there it''s a five-minute walk to Europe Square, anchored by a statue of Medea holding the Golden Fleece, and to the narrow lanes of the old town in between, lined with 19th-century merchant houses, wine bars and street cafes. Both squares also run their own evening fountain shows. It''s a compact, walkable pocket that rewards an unhurried wander rather than a checklist visit.', 'Free to wander. Livelier and cooler in the early evening, when cafe terraces fill up and the fountains at both squares start running.', 'Early evening', 60, '1 hr', NULL, NULL, 'Free', 'Batumi', 41.649594, 41.641122, 'Flat, traffic-free, and full of gelato stalls — an easy stroll for tired legs.', false, ARRAY['walk']::TEXT[], 2, NULL, NULL),
  ('batumi-adjara-art-museum', 'batumi-adjara', 'State Art Museum of Adjara', 'Georgian and Adjaran painting, sculpture and icons indoors — the region''s best answer to a rainy day.', 'This small, central museum on Gorgiladze Street holds a permanent collection of Georgian and Adjaran painting, graphic art, sculpture and religious icons across a manageable handful of rooms. It''s not a destination in itself the way the boulevard or Gonio Fortress are, but it''s genuinely worthwhile and fully indoors, which makes it the natural fallback when Adjara''s rain sets in. Labels are mixed Georgian/English; the collection rewards 45 minutes to an hour rather than a rushed pass-through.', 'Closed Mondays; open 10:00-18:00 the rest of the week. Standard ticket ₾6, ₾7 with a guided excursion; children aged 6-14 pay ₾1 as part of a family ticket, under 6 free.', NULL, 60, '1 hr', 6, 7, '₾6-7 per person', 'Batumi', 41.648622, 41.633863, NULL, false, ARRAY['cool']::TEXT[], 3, NULL, NULL),
  ('batumi-adjara-ali-and-nino', 'batumi-adjara', 'Ali and Nino ("Statue of Love")', 'Two moving metal figures glide together, merge, and pass through one another on the boulevard each evening.', 'Sculptor Tamara Kvesitadze''s kinetic artwork depicts the star-crossed lovers of the novel "Ali and Nino": two 8-meter steel silhouettes that slide toward each other along a track, merge into a single form, and then separate again over roughly a ten-minute cycle. It sits directly on the boulevard near the Alphabet Tower and draws a crowd every evening once it''s dark enough for the lighting to read well. There''s no ticket and no barrier — you simply wait for the cycle if the figures aren''t moving when you arrive.', 'No officially posted schedule; it''s widely reported to start moving from around 7pm and repeat every ten minutes or so through the evening, but timing isn''t guaranteed — if it''s static when you arrive, give it 10-15 minutes or come back after dark.', 'After dark, roughly 7-9pm', 20, '20 min', NULL, NULL, 'Free', 'Batumi', 41.655576, 41.643066, 'Kids get a kick out of watching the two figures "walk through" each other — worth timing your evening around it.', false, ARRAY['evening', 'scenic']::TEXT[], 4, NULL, NULL),
  ('batumi-adjara-chacha-tower', 'batumi-adjara', 'Chacha Tower', 'A clock tower on the boulevard that, at least on paper, once poured chacha from a spout each evening.', 'This 25-meter Ottoman-style clock tower, a deliberate replica of a 1901 landmark in Izmir, was built in 2012 with a novelty feature: a spout designed to run with chacha, Georgia''s grape brandy, for ten minutes each evening. It''s now more a curiosity than a functioning attraction — recent visitor reports describe the clock as stopped and the fountain function as inconsistent or not running, and the stairs to the small observation deck have been reported fenced off. Treat it as a two-minute photo stop on the boulevard rather than something to plan an evening around.', 'Do not count on the chacha fountain running or the tower being open to climb — both are inconsistently reported as non-functional or closed as of recent visits. Confirm locally if either matters to your plans; otherwise it''s a free exterior landmark on the walk along the boulevard.', NULL, 10, '10 min', NULL, NULL, 'Free', 'Batumi', 41.652806, 41.642639, NULL, false, ARRAY['evening']::TEXT[], 5, NULL, NULL),
  ('batumi-adjara-khachapuri-house', 'batumi-adjara', 'House of Adjarian Khachapuri', 'The boat-shaped, egg-topped khachapuri that gave the dish its name, at the spot rated best in the world.', 'Adjaruli khachapuri — an open canoe of bread filled with cheese and topped with a raw egg and a slab of butter that you stir into the melted cheese at the table — originates in this region, and this small, unpretentious restaurant in Old Batumi has been rated the world''s best for it by TasteAtlas. The ritual is simple: tear the crust from the edges, dip it in the molten cheese-egg-butter center, and keep going. A medium khachapuri easily feeds two, and a simple cucumber-tomato salad on the side is the only accompaniment you need.', 'A medium khachapuri runs about ₾18. It''s a small, popular spot with no confirmed reservation system — go hungry and expect a short wait at peak lunch and dinner times. One khachapuri comfortably feeds two people.', NULL, 60, '1 hr', 15, 25, '₾15-25 per person', 'Batumi', 41.645995, 41.633507, 'Rich and filling — one order shared between two kids is usually plenty.', false, ARRAY['wine']::TEXT[], 6, NULL, NULL),
  ('batumi-adjara-botanical-garden', 'batumi-adjara', 'Batumi Botanical Garden', 'Nine world climate zones of subtropical forest tumbling down a seaside cape north of the city.', 'Founded in 1912 by the Russian botanist Andrei Krasnov, this 108-hectare garden covers the cliffs of Mtsvane Kontskhi ("Green Cape") with terraced sections organized by world region — Caucasus, Himalayan, East Asian, Mexican, Australian and more — connected by winding paths with sea views through the trees. It''s large and hilly enough that seeing even a good cross-section takes real time, and the entrance used here is the main southern gate closest to Batumi, not the geographic center of the grounds. An electric buggy service is available for anyone who doesn''t want to walk the whole length.', '₾20 for foreign visitors, ₾10 for Georgian citizens; children under 6 free. Open daily 9:00-17:30 (until 20:00 in summer). Electric buggy hire is roughly ₾10 one-way if you don''t want to walk the entire garden.', 'Morning, before the day heats up', 150, '2.5 hr', 10, 20, '₾10-20', 'Mtsvane Kontskhi', 41.692008, 41.707329, 'Big and hilly with a lot of ground to cover — the electric buggy is worth it with tired kids.', false, ARRAY['walk', 'scenic', 'cool']::TEXT[], 7, NULL, NULL),
  ('batumi-adjara-gonio-fortress', 'batumi-adjara', 'Gonio-Apsaros Fortress', 'Roman-era fortress walls at the mouth of the Chorokhi River, layered with 2,000 years of history.', 'Built as the Roman fortification of Apsaros in the 1st century AD and later held by Byzantine, Genoese and Ottoman garrisons in turn, Gonio''s rectangular perimeter wall — roughly 900 meters around — still stands largely intact, enclosing excavated bath houses, barracks foundations and a small on-site museum. Local tradition holds that the apostle Matthias is buried within the grounds. It''s an easy, mostly flat walk around the walls and interior, with far fewer crowds than anything on the Batumi boulevard.', '₾15 for foreign visitors, ₾10 for Georgian citizens; children under 6 free, ages 6-16 ₾2. Generally open 10:00-18:00, though sources disagree on whether it closes Mondays — confirm locally if visiting off-season.', NULL, 60, '1 hr', 10, 15, '₾10-15 per person', 'Gonio', 41.573264, 41.573816, 'Open walls to climb and a lot of grassy space to run around, but little shade — bring water in summer.', false, ARRAY['walk', 'scenic']::TEXT[], 8, NULL, NULL),
  ('batumi-adjara-sarpi-beach', 'batumi-adjara', 'Sarpi Beach & the Georgia-Turkey Border', 'A pebble beach that runs right up to the border fence, with Turkey visible across the frontier line.', 'Sarpi, about 18km south of Batumi, is Georgia''s southernmost coastal village and sits directly on the border with Turkey — the crossing here operates 24 hours a day. The free public pebble beach runs close enough to the frontier that you can see the checkpoint and Turkish hillside beyond, giving it a novelty most Georgian beaches don''t have, alongside being quieter and less developed than central Batumi''s waterfront. It''s a straightforward add-on to a Gonio Fortress visit rather than a destination on its own.', 'Free, with only a couple of seasonal cafes for facilities — bring your own water and shade. This is an active border zone: stay on the beach and don''t approach or photograph the checkpoint itself.', NULL, 45, '45 min', NULL, NULL, 'Free', 'Sarpi', 41.523659, 41.548288, 'Pebble beach rather than sand — water shoes make it much more comfortable.', false, ARRAY['water']::TEXT[], 9, NULL, NULL),
  ('batumi-adjara-mtirala-national-park', 'batumi-adjara', 'Mtirala National Park', 'Georgia''s wettest national park: a rainforest-green ridge with a real day hike to a waterfall and a lake.', 'Mtirala — "the crying one" — is named for having the highest rainfall in Georgia, and the payoff is dense, permanently green Colchic mixed forest draped over steep inland ridges southeast of Batumi. The visitor center and trailhead sit in the village of Chakvistavi; the main marked trail climbs through the forest to a waterfall and a small lake, a genuine half-day hike rather than a short walk. A short zipline near the visitor center offers a lighter-effort taste of the park for anyone not up for the full trail.', 'Entrance to the park is free; the waterfall-and-lake trail is a real hike, roughly 7km round trip and 3.5-4 hours — budget accordingly and wear proper shoes. A short zipline near the visitor center runs roughly ₾15-20. The access road from Chakvi is narrow and partly unpaved, so drive it slowly.', 'Morning start, to have daylight margin for the full trail', 240, '4 hr', NULL, NULL, 'Free', 'Chakvi', 41.680078, 41.860252, 'The full hike is long for young kids; the visitor-center area and short zipline are a better match for younger children.', false, ARRAY['hike', 'water']::TEXT[], 10, NULL, NULL),
  ('batumi-adjara-makhuntseti-waterfall', 'batumi-adjara', 'Makhuntseti Waterfall', 'A 48-meter curtain of water dropping into a plunge pool, barely a hundred meters off the Keda road.', 'Near the village of Zeda Makhuntseti in Keda municipality, about 30km and under an hour from Batumi up the Acharistsqali valley, this waterfall is one of the tallest in Adjara and one of the easiest to reach — a short, flat walk from roadside parking brings you straight to a viewing point at the base. Roadside stalls sell local honey and fruit, especially in the warmer months. It''s typically paired with the Queen Tamar arch bridge a short distance further up the same road.', 'No entrance fee; roadside parking costs about ₾2. Visit alongside the Queen Tamar Bridge just up the valley rather than as a standalone stop — budget time for both.', NULL, 30, '30 min', NULL, NULL, 'Free', 'Makhuntseti', 41.574938, 41.858308, 'Flat, short walk right to the viewing point — easy going with kids.', false, ARRAY['water', 'walk']::TEXT[], 11, NULL, NULL),
  ('batumi-adjara-tamar-bridge', 'batumi-adjara', 'Queen Tamar''s Arch Bridge, Makhuntseti', 'A single stone arch over the Acharistsqali gorge, named for the queen of Georgia''s medieval golden age.', 'This medieval single-span stone bridge, roughly 20 meters long and 6 meters above the Acharistsqali river, carries the name of Queen Tamar, whose 12th-13th century reign is remembered as Georgia''s golden age, though the bridge''s exact construction date is disputed. It sits a short distance up the valley road from Makhuntseti Waterfall, with small cafes and a roadside winery nearby. Walk out onto the arch itself, then down to the riverbank below for the classic view of the span framed by the gorge.', 'Free to walk onto the bridge; roadside parking costs about ₾2. Visit together with Makhuntseti Waterfall just downstream rather than as a separate trip.', NULL, 25, '25 min', NULL, NULL, 'Free', 'Makhuntseti', 41.571021, 41.860057, 'Low walls in places on the arch itself — hold hands near the edges.', false, ARRAY['scenic', 'walk']::TEXT[], 12, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Borjomi & Bakuriani — 11 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Mineral springs, forest, cool air',
  summary       = 'Borjomi and Bakuriani are Georgia''s classic mountain escape from the summer heat: a spa town built around a famous sulfurous mineral spring, and a pine-forested ski resort 30km and 900m higher up the valley. Between them you get a mineral-water park with rides, forest trails and a hidden monastery, open-air sulfur pools, and — in winter — Georgia''s most beginner-friendly ski slopes. It''s cheap, green, noticeably cooler than Tbilisi, and genuinely built for families.',
  when_to_go    = 'This is the region Tbilisi families flee to when the capital hits 35C+ in July-August — Borjomi (820m) and especially Bakuriani (1,700m) run several degrees cooler, with real shade in the forests. In Borjomi Park, go before 9am (free entry, and not yet hot) and save the cable car and any hiking for late afternoon. December to late March is the other high season, when Bakuriani becomes Georgia''s main family ski resort (season roughly Dec 20 - Mar 29, confirm each year). Shoulder months (Apr-May, Oct-Nov) are quiet but grey and muddy, with limited lift and outdoor operation.',
  getting_there = 'Borjomi is about 150km / 2-2.5hr from Tbilisi via good tarmac (through Khashuri); marshrutkas run from Didube station (~3hr, a few GEL). Bakuriani is a further 30km / roughly 1hr by marshrutka or taxi from Borjomi (frequent minibuses, ~3-5 GEL), or reachable direct from Tbilisi by marshrutka/taxi (~3hr). The historic ''Kukushka'' narrow-gauge railway between Borjomi and Bakuriani has been suspended since 2020-2022 with no confirmed restart date — do not plan around it; treat any relaunch as a bonus, not a given.',
  base_towns    = 'Borjomi has the wider choice of hotels and spa guesthouses and sits closer to the park, sulfur pools and national park gate. Bakuriani, higher and cooler, is the better base in winter for ski-in convenience and in peak summer if you want maximum relief from the heat; it has plenty of family-oriented A-frame guesthouses but a thinner restaurant scene than Borjomi.'
WHERE id = 'borjomi-bakuriani';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('borjomi-bakuriani-central-park', 'borjomi-bakuriani', 'Borjomi Central Park', 'Georgia''s famous mineral-water park — spring tastings, a small funfair, and shaded paths along the Borjomula River.', 'The park is built around Ekaterine''s Spring, where you can fill a bottle straight from the source of Borjomi''s famous mineral water — warm, salty and sulfurous, and usually good for a laugh from kids on first taste. Beyond the spring pavilion there are shaded walking paths, cafes, a small funfair with rides for younger kids, and the old bottling-factory building (now a chess club and library) near the entrance. It''s the natural anchor for a Borjomi day and the starting point for both the cable car and the walk to the sulfur pools.', 'Entry is 5 GEL (free for kids under 8, and free for everyone 6-9am). Open 6am-8pm daily. Funfair rides are paid separately, on top of entry.', 'Before 9am (free entry, cooler) or early evening', 120, '2 hr', 5, 5, '₾5', 'Borjomi', 41.832216, 43.393669, 'Playground, small carnival rides, and a spring most kids find hilarious rather than pleasant — a good icebreaker for the trip.', false, ARRAY['kids', 'cool', 'walk']::TEXT[], 1, NULL, NULL),
  ('borjomi-bakuriani-ropeway', 'borjomi-bakuriani', 'Borjomi Park Cable Car', 'A cable car running since 1962 lifts you from the park to a forested plateau with a Ferris wheel and valley views.', 'This small cable car (up to 25 passengers per cabin) climbs from inside Central Park to a plateau above the gorge, with views over Borjomi town, the valley, and the Borjomula River. At the top there''s an old Ferris wheel, a small church, and a cafe serving Georgian food and drinks. The ride itself is only a few minutes, but it''s the easiest way in the region to get a proper elevated view without any walking.', 'Around 15 GEL one-way (roughly double for return); runs about 10am-8pm but can pause in high wind or heavy rain. Georgian ropeways have had past safety-driven closures nationwide, so confirm it''s running before you queue.', 'Late afternoon, for the light over the valley', 45, '45 min', 15, 25, '₾15-25', 'Borjomi', 41.8348, 43.3972, 'A short, exciting ride kids love; the old Ferris wheel at the top is a nice bonus if it happens to be running.', false, ARRAY['scenic', 'cool', 'kids']::TEXT[], 2, NULL, NULL),
  ('borjomi-bakuriani-sulfur-pools', 'borjomi-bakuriani', 'Borjomi Sulfur Pools', 'Open-air sulfur pools tucked in the forest above town — Borjomi''s quieter answer to Tbilisi''s bathhouses.', 'About a 3km walk (or short drive) through forest from Central Park, these open-air pools are fed by the same mineral springs that made Borjomi famous, but without Tbilisi''s crowds or architecture. Several pools run at different temperatures, and the setting — surrounded by trees, away from the town center — makes it feel more like a forest spring than a spa. It''s a good one to slot in on a cooler or overcast day, since the water stays warm regardless of the weather.', '15 GEL per person, free under 8; open 6am-8pm daily. Bring a towel and sandals. Can get crowded and less pleasant at peak summer midday — go early or on a cooler day.', 'Early morning, or a cool/overcast day', 60, '1 hr', 15, 15, '₾15', 'Borjomi', 41.845, 43.4, 'The sulfur smell can put younger kids off at first, but most come around once they''re in the warm water.', false, ARRAY['water', 'cool']::TEXT[], 3, NULL, NULL),
  ('borjomi-bakuriani-kharagauli-np', 'borjomi-bakuriani', 'Borjomi-Kharagauli National Park (Likani Gate)', 'Cool, quiet pine forest trails into one of Georgia''s largest protected parks, entered from the Likani gate.', 'The national park''s main marked route from here, the Footprint Trail, runs a demanding 13km/6-8hr — too long for most families with young kids — but the first stretch along the Borjomistsqali river out of the Likani guard station makes a genuinely pleasant, shaded, mostly flat forest walk before the trail starts climbing. It''s a low-key contrast to the busier, paid attractions in town: free, quiet, and a good way to actually be in the forest the region is named for rather than just look at it.', 'Free, but you must register for a free safety permit (bring ID) either at the National Park office in Borjomi or the Likani gate before setting out. Stick to the first 1-2km with younger kids and turn back before the climb starts.', 'Morning, before the heat builds', 90, '1.5 hr', NULL, NULL, 'Free', 'Borjomi', 41.826, 43.36, 'Shaded and mostly flat near the gate — a real forest walk without demanding much of little legs, as long as you turn back before the trail climbs.', false, ARRAY['cool', 'walk']::TEXT[], 4, NULL, NULL),
  ('borjomi-bakuriani-green-monastery', 'borjomi-bakuriani', 'Green Monastery (Chitakhevi)', 'A hushed 9th-century forest monastery most Borjomi day-trippers never find, a 45-minute walk from the road.', 'Named for the moss and forest that wrap its stone walls, the Green Monastery (Mtsvane Monastery) sits in the Chitakhevi valley about 12km from Borjomi, tracing back to the 9th century. It''s still an active monastic site, small and unpolished rather than restored-for-tourists, and gets a fraction of the visitors that the town''s mineral park does. The last stretch is on foot along an unpaved forest track, which makes the arrival feel earned rather than just another parking-lot stop.', 'Free. The final approach is roughly 45 minutes on foot each way along an unpaved track — a normal car can get close in dry weather, but check conditions after rain. Modest dress expected as at any active monastery.', 'Morning', 120, '2 hr', NULL, NULL, 'Free', 'Borjomi', 41.810833, 43.309843, 'Frame the walk-in as a hike to a hidden, forgotten monastery — the approach is half the appeal for kids.', false, ARRAY['walk', 'scenic']::TEXT[], 5, NULL, NULL),
  ('borjomi-bakuriani-cafe-iggy', 'borjomi-bakuriani', 'Cafe Iggy', 'A heritage-building restaurant on Kostava Square doing standout Georgian cooking, including Borjomi trout.', 'Opened in 2022 in a restored heritage building, Cafe Iggy is the destination meal in Borjomi rather than just a refuel — known for mini khinkali in pepper sauce and local trout baked in vine leaves with pomegranate sauce. The indoor dining room makes it the region''s most reliable wet-weather option, and it''s central enough to slot in after the park or before heading toward Bakuriani.', 'Fully indoor. Popular at lunch on weekends — arrive by 1pm to avoid a wait, since it doesn''t appear to take phone reservations.', 'Lunch', 90, '1.5 hr', 25, 45, '₾25-45 per person', 'Borjomi', 41.841227, 43.382118, 'Menu has simple grilled and khinkali options kids will actually eat, and an indoor table is a welcome break if they need to sit still for a bit.', false, ARRAY['wine']::TEXT[], 6, NULL, NULL),
  ('borjomi-bakuriani-town-walk', 'borjomi-bakuriani', 'Bakuriani Town & Trinity Church', 'A-frame chalets, pine air, and a tiny hilltop church make for an easy first taste of Bakuriani.', 'Central Bakuriani is small and walkable: wander past the A-frame guesthouses and gear shops, cut through the forested Amirani''s Park, and climb under 10 minutes to the humble Trinity Church, perched on the rim of the extinct Mukhera volcanic crater above town. It''s a low-key, no-agenda way to get oriented before heading to the lifts or slopes, and Amirani''s Park has open ground for kids to run off car-trip energy.', 'Free and open-ended. Amirani''s Park has playgrounds and, in winter, space for sledding and snowman-building.', NULL, 60, '1 hr', NULL, NULL, 'Free', 'Bakuriani', 41.752529, 43.524837, 'Amirani''s Park gives kids room to run (or sled, in winter) right after the drive up — an easy way to burn energy before anything else.', false, ARRAY['walk', 'kids', 'cool']::TEXT[], 7, NULL, NULL),
  ('borjomi-bakuriani-kokhta-cable-car', 'borjomi-bakuriani', 'Kokhta Cable Car', 'A gondola up Mount Kokhta for sunset views and a mountaintop cafe, running through both winter and summer.', 'The same lift network that carries skiers up Mount Kokhta in winter also runs for sightseers, including in summer — a scenic, enclosed ride up through forest to a station with wide views over Bakuriani and the Trialeti range, plus a cafe at the top for a coffee or meal with a view. It requires no fitness at all, which makes it one of the easiest big-payoff views in the whole region.', 'Around 25 GEL return; typically runs roughly 10am-10pm, but summer sightseeing operation on Bakuriani''s lifts has in past years only started in early July — confirm current dates and hours locally before building a day around it.', 'Late afternoon into sunset', 60, '1 hr', 25, 25, '₾25 return', 'Bakuriani', 41.742, 43.548, 'An easy, enclosed cable-car ride with a big view payoff and no walking required.', false, ARRAY['scenic', 'cool', 'evening']::TEXT[], 8, NULL, NULL),
  ('borjomi-bakuriani-alpine-coaster', 'borjomi-bakuriani', 'Didveli Alpine Coaster', 'A gravity-powered rail coaster twisting down the Didveli hillside — Bakuriani''s one real adrenaline hit for kids.', 'This toboggan-style alpine coaster runs on a fixed rail through the forest at the Didveli lift base, with riders controlling their own speed via a hand brake. It''s independent of the ski lifts and, unlike most of the region''s attractions, is built specifically to be repeated — a short, queue-friendly ride that older kids will want to do more than once.', 'Price and which months it runs vary year to year — confirm locally, especially for a summer visit, since operating hours can be limited outside ski season. There''s likely a minimum height or age for solo riders; check at the ticket booth. The fare is charged per ride, not as a day pass.', NULL, 30, '30 min', 15, 30, '₾15-30', 'Bakuriani', 41.728042, 43.531597, 'The single most thrilling five minutes in the region for kids old enough to ride solo; younger kids can usually ride tandem with an adult.', false, ARRAY['thrill', 'kids']::TEXT[], 9, NULL, NULL),
  ('borjomi-bakuriani-skiing', 'borjomi-bakuriani', 'Bakuriani Skiing', 'Georgia''s most family-friendly ski resort, with a dedicated beginner slope and ski schools built for kids.', 'Bakuriani spreads across the Didveli, Kokhta, and Mitarbi areas with around 20 lifts in total, but it''s best known as the easiest place in Georgia to put a beginner — kid or adult — on skis for the first time, thanks to the gentle ''25 Ski Park'' slope and widely available children''s instructors. The 2025/26 season opened Kokhta on Dec 20 and Didveli/Mitarbi on Dec 27, closing Mar 29 — treat those as approximate and confirm the current year''s dates.', 'Day lift pass roughly ₾55 adult / ₾28 for kids 6-12; ticket booths open around 10am-4:45pm. Private lessons run roughly ₾70-100/hr. Renting gear in town is usually cheaper than at the lift base.', 'January-February for the most reliable snow', 240, '4 hr', 28, 55, '₾28-55', 'Bakuriani', 41.7315, 43.528, 'The ''25 Ski Park'' beginner slope and dedicated kids'' instructors make this the easiest first-ever ski day in Georgia.', false, ARRAY['thrill', 'cool']::TEXT[], 10, NULL, NULL),
  ('borjomi-bakuriani-joyland', 'borjomi-bakuriani', 'Joyland Park', 'A snow-tubing and family fun park with zones for toddlers up to bigger kids, right in Bakuriani.', 'Joyland is built squarely for families, split into three zones — Skyland, Tubingland, and Babyland — with tubing runs and rides scaled to different ages, plus an ATV rental kiosk nearby for older kids and adults. It''s primarily a winter, snow-based attraction; some form of it may run in warmer months, but that''s unconfirmed, so it''s a stronger bet for a winter ski trip than a summer one.', 'Primarily a winter (snow-tubing) attraction — summer-season hours and which rides operate then are unconfirmed, so check locally before planning a summer visit around it. What you pay depends on which activities you actually do.', 'Winter', 90, '1.5 hr', 10, 30, '₾10-30', 'Bakuriani', 41.74759, 43.526487, 'Purpose-built for younger kids — the ''Babyland'' zone is aimed at the littlest ones, with tubing runs for older siblings.', false, ARRAY['kids', 'thrill']::TEXT[], 11, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Gudauri & Kazbegi — 12 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Alpine, cool, glaciers',
  summary       = 'The Georgian Military Highway climbs over the 2,379m Jvari Pass into Georgia''s high Caucasus, pairing the Gudauri ski plateau with Stepantsminda (still widely called Kazbegi) under the glaciers of Mount Kazbek. The hilltop Gergeti Trinity Church is the postcard, but the region also holds a ghost valley of mineral springs, a dead-end alpine hiking village, and the last stretch of road before Russia. It''s the coolest, greenest part of any Georgia itinerary — and the most weather-dependent.',
  when_to_go    = 'Summer (June-September) is when everything is open: Truso and Juta valleys are only accessible roughly late May through October, and the high passes are least likely to close. Mornings give the best odds of a cloud-free Kazbek — the peak is wrapped in cloud more often than not by early afternoon, even in July. Winter (December-March) turns Gudauri into a proper ski resort but makes Kazbegi sightseeing weather-dependent and occasionally impossible: the Jvari Pass has closed repeatedly in recent winters for avalanches and heavy snow, sometimes for days at a stretch. Whatever the season, build a spare half-day into the itinerary rather than scheduling the pass crossing as your last commitment before a flight.',
  getting_there = 'From Tbilisi, the Georgian Military Highway (E117) reaches Gudauri in about 2 hours (120 km) and Stepantsminda in about 2.5-3 hours (157 km) — paved and generally good, but it climbs over the 2,379m Jvari Pass, which is the region''s real bottleneck. The pass has recorded multiple full and partial closures in 2026 alone (avalanche closures in January, heavy-snow closures in February-March), and can also see avalanche-gate delays and truck queues even when technically open, mainly driven by traffic for Verkhny Lars/Dariali — the only Georgia-Russia land border crossing, a few kilometres past Stepantsminda. Check pass status the morning you travel. Marshrutkas run from Tbilisi''s Didube station to Kazbegi (roughly 3 hours, a few GEL); getting between Gudauri and the smaller Kazbegi sights without a car is difficult, so most visitors drive, hire a taxi, or book a tour.',
  base_towns    = 'Stepantsminda (Kazbegi) is the practical base for most of this list — walking distance to the Gergeti 4x4 pickup point, with the widest range of guesthouses and the Rooms Hotel. Gudauri, about 40 minutes south over the pass, is the resort base and makes most sense in ski season or if paragliding is the priority. Splitting a couple of nights between both suits a fuller itinerary.'
WHERE id = 'gudauri-kazbegi';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('gudauri-kazbegi-gergeti-trinity', 'gudauri-kazbegi', 'Gergeti Trinity Church', 'Georgia''s most photographed church, perched alone on a ridge under Mount Kazbek — not in the town below it.', 'This 14th-century Holy Trinity Church stands alone on a ridge at 2,170m above Stepantsminda, its cross-cupola silhouette set against Kazbek''s glaciers when the cloud lifts. Most visitors reach it by shared 4x4 from the town''s main square (about 20 minutes each way on a rough but graded track); the alternative is a steep 1.5-2 hour hike. The chapel interior is small and plain — the setting, not the architecture, is the reason to come. Kazbek itself is cloud-wrapped more often than not, so mornings give the best odds of a clear view.', 'The 4x4 track starts from Stepantsminda''s main square; drivers usually wait for a full jeep (4-6 people) before leaving. Expect roughly ₾15-30 per person for a shared round trip, or ₾70-100 to charter the whole vehicle. Cover shoulders and knees for the church. Kazbek is frequently in cloud by midday, whatever the forecast said that morning.', 'Early morning, before cloud builds over Kazbek', 90, '1.5 hr', 15, 30, '₾15-30', 'Stepantsminda', 42.6624, 44.6205, 'The 4x4 ride up is half the fun for kids; hold on tight on the rough track. The steep hiking alternative isn''t realistic with small children.', false, ARRAY['scenic', 'walk']::TEXT[], 1, NULL, NULL),
  ('gudauri-kazbegi-stepantsminda-wander', 'gudauri-kazbegi', 'Stepantsminda Town Wander', 'The alpine base town itself — Terek riverside, guesthouse cafes, and your first look up at Kazbek.', 'Stepantsminda (most drivers and maps still say Kazbegi) is a small grid of streets along the Terek River at 1,740m, with guesthouses, a handful of cafes, and a main square where 4x4 drivers gather for the Gergeti run. It isn''t a sight so much as the region''s hub — worth half an hour to get oriented, change money, and look up at Kazbek framed between buildings on a clear day. It also makes a reasonable place to wait out weather before deciding on the pass or a 4x4 trip.', 'ATMs and a few grocery shops line the main street; card acceptance is patchy elsewhere in the region, so stock up on cash here before heading to Gergeti, Truso, or Juta.', NULL, 45, '45 min', NULL, NULL, 'Free', 'Stepantsminda', 42.6575, 44.64528, 'Flat, easy streets with a couple of playgrounds near the square.', false, ARRAY['walk']::TEXT[], 2, NULL, NULL),
  ('gudauri-kazbegi-gveleti-waterfall', 'gudauri-kazbegi', 'Gveleti Waterfall Hike', 'A shaded riverside walk to twin waterfalls near the Russian border, cooler than anything in town.', 'From a parking area on the Dariali side road, a marked trail follows the Gveleti stream through forest to the Small Gveleti Waterfall (20-30 easy minutes), with the 25m Big Gveleti Waterfall another steeper 45-60 minutes beyond it, over rougher ground with some scrambling and a cable handhold section. It''s one of the few genuinely shaded, cool walks in the region — a good match for a hot afternoon between more exposed stops. The water is glacial-cold and fast year-round.', 'Roadside parking costs around ₾5; the track beyond it is unpaved and rough, so leave a rental car there rather than driving further in. The final stretch up to the Big Waterfall is steep and can be slippery — wear real shoes, not sandals.', 'Midday, for the cool of the canyon', 120, '2 hr', NULL, NULL, 'Free', 'Gveleti', 42.70722, 44.62361, 'The lower Small Waterfall is an easy family walk; save the scrambly upper path for kids who hike confidently.', false, ARRAY['cool', 'walk', 'water']::TEXT[], 3, NULL, NULL),
  ('gudauri-kazbegi-sno-stone-heads', 'gudauri-kazbegi', 'Sno Village Stone Heads', 'Six giant granite heads of Georgian writers and heroes, carved into a roadside meadow.', 'A short detour off the Sno road, local sculptor Merab Piranishvili carved six monumental heads — Rustaveli, Chavchavadze, Tsereteli, Vazha-Pshavela, Alexander Kazbegi, and Christ — each from a single block of granite, set in an open meadow with the Sno valley peaks behind. It''s an easy, quick, slightly surreal stop that breaks up the drive to or from Juta or the horse-riding stables, and needs no more than a short stroll among the sculptures.', 'No fee and no fences — just pull off the road. Best light is late afternoon, when the low sun catches the carved faces.', 'Late afternoon', 20, '20 min', NULL, NULL, 'Free', 'Sno', 42.608209, 44.630906, 'Kids enjoy posing near (not on) the giant heads for photos.', false, ARRAY['scenic', 'kids']::TEXT[], 4, NULL, NULL),
  ('gudauri-kazbegi-friendship-monument', 'gudauri-kazbegi', 'Russia-Georgia Friendship Monument', 'A Soviet-era mosaic rotunda on the Jvari Pass with the best roadside panorama on the whole highway.', 'Built in 1983 to mark 200 years of the Treaty of Georgievsk, this circular mosaic-clad monument sits directly on the Georgian Military Highway between Gudauri and the 2,379m Jvari Pass, framing an enormous view down the Devil''s Valley toward the Khevi mountains. The mosaics lining the inside depict Georgian and Russian historical scenes. It''s a five-minute stop built into almost every Kazbegi drive, but worth actually getting out of the car for rather than just slowing down.', 'Roadside pull-off with vendor stalls selling honey, churchkhela, and knitwear — a convenient snack or bathroom break in either direction. Exposed and often windy, even in summer.', NULL, 20, '20 min', NULL, NULL, 'Free', 'Gudauri', 42.492, 44.4527, 'Easy, flat viewing area, but there are low walls kids like to climb — supervise near the edge.', false, ARRAY['scenic']::TEXT[], 5, NULL, NULL),
  ('gudauri-kazbegi-truso-valley', 'gudauri-kazbegi', 'Truso Valley', 'Ghost Ossetian villages and orange mineral-spring terraces, in a valley most day-trippers never turn off for.', 'West of the highway at Kobi, a rough 4x4 track climbs the Terek''s tributary into Truso Gorge, past travertine terraces stained white and orange by iron-rich mineral springs, ruined medieval watchtowers, and the abandoned village of Ketrisi. Guided 4x4 trips or hikes continue toward the ruined Zakagori fortress; beyond it, a free border-zone permit (checked on the spot by the military post, roughly a 30-minute process) is required, since the valley runs along the administrative boundary with South Ossetia. Most Kazbegi visitors never make the detour, which is much of the appeal.', 'The road is only reliably open roughly late May-October, closed by snow or mud outside that window. Local drivers from Stepantsminda''s main square typically charge ₾40-60 one-way or ₾80-100 return for the 4x4 leg; guided day tours cost more. Stay on the marked track — red-and-white boundary posts mark the actual border and must not be crossed.', 'Late morning, once the border post is staffed', 300, '5 hr', 40, 100, '₾40-100', 'Kobi', 42.583217, 44.427433, 'A long day on a rough, bumpy track — better suited to older kids than toddlers.', false, ARRAY['scenic', 'hike']::TEXT[], 6, NULL, NULL),
  ('gudauri-kazbegi-dariali-monastery', 'gudauri-kazbegi', 'Dariali Monastery Complex', 'A striking monastery built to look medieval, a few hundred meters from Georgia''s last checkpoint before Russia.', 'Consecrated in 2011 but modelled on the 11th-century Nikortsminda church, the Archangels Michael and Gabriel complex sits in the narrow Dariali Gorge, its hewn pinkish-grey stone, mosaics, and metalwork largely made by the resident monks themselves. It''s the last real stop before the highway reaches the Verkhny Lars/Dariali border post with Russia, so most self-drivers focused on the crossing ahead blow straight past it. Free to enter, quiet, and a striking contrast to Gergeti''s crowds a few kilometres south.', 'This is a working monastery right up against a sensitive border zone — dress modestly, stay within the complex, and don''t photograph the border infrastructure just beyond it. No entrance fee.', NULL, 30, '30 min', NULL, NULL, 'Free', 'Stepantsminda', 42.73554, 44.6314, NULL, false, ARRAY['scenic']::TEXT[], 7, NULL, NULL),
  ('gudauri-kazbegi-juta-chaukhi', 'gudauri-kazbegi', 'Juta Village & Chaukhi Valley', 'A dead-end alpine village under the jagged Chaukhi massif, and the trailhead for one of Georgia''s best day hikes.', 'A rough side road climbs about 12km from Sno to Juta, a scatter of guesthouses at 2,200m under the serrated Chaukhi massif (3,842m), sometimes nicknamed the Georgian Dolomites. From the village, a well-marked trail follows the Chaukhistskali river up the valley toward a small lake and glacier views, walkable as an out-and-back of almost any length depending on stamina. The Fifth Season guesthouse just outside the village is the usual last-food stop before the trail proper. This is the pick for travelers who want one real mountain hike rather than a string of roadside viewpoints.', 'The access road needs a high-clearance vehicle or a 4x4 taxi from Stepantsminda (about 45-60 minutes); an ordinary rental car will struggle on the final stretch. Weather turns fast above the treeline — carry a warm layer even on a clear morning.', 'Morning start, to be back below cloud before afternoon storms build', 300, '5 hr', NULL, NULL, 'Free', 'Juta', 42.578532, 44.744107, 'The first hour along the valley floor suits older, fit kids; the full route to the lake is a proper trek.', false, ARRAY['hike', 'scenic', 'cool']::TEXT[], 8, NULL, NULL),
  ('gudauri-kazbegi-paragliding', 'gudauri-kazbegi', 'Gudauri Tandem Paragliding', 'Launch from the ski slopes and float 15-20 minutes over the Gudauri valley with a licensed tandem pilot.', 'Several operators based around the Gudauri resort run tandem paragliding, launching from points on the upper slopes reached by chairlift and landing in a field near the main road. Flights themselves run roughly 15-20 minutes and need nothing more than closed shoes — the licensed pilot does the flying. It''s entirely weather-dependent: wind or low cloud delays or cancels flights outright, so treat it as a flexible add-on rather than something to schedule right before you need to leave.', 'Meeting points vary by operator — confirm the exact pickup spot when booking. Bring cash; card readers aren''t reliable roadside. Photo and video packages cost extra on top of the flight price.', 'Calm mid-morning conditions; afternoons often bring wind', 60, '1 hr', 100, 250, '₾100-250', 'Gudauri', 42.477, 44.479, 'Most operators set a minimum age, commonly around 10-12 — confirm before booking with kids.', true, ARRAY['thrill', 'scenic']::TEXT[], 9, NULL, NULL),
  ('gudauri-kazbegi-horse-riding', 'gudauri-kazbegi', 'Kazbegi Horse Riding', 'Guided rides into the Sno valley meadows — beginner-friendly, with Kazbek and the Gergeti glacier in view.', 'Stables at the edge of Stepantsminda run guided horse treks into the Sno valley and along the Artkhmo gorge, typically 2.5-4 hours depending on the route, crossing open alpine pasture with the Gergeti glacier visible behind you. No riding experience is assumed — horses are led or closely guided at a walk or gentle trot. Longer routes push toward Truso valley territory for more confident riders.', 'Book the evening before through your guesthouse or directly at a stable — this is a first-come local operation, not a call-ahead agency. Wear long trousers and closed shoes; ask about helmets, as provision varies by stable. The price swings with the route and how long you ride — agree it before setting off.', 'Morning, before afternoon cloud and wind pick up', 180, '3 hr', 130, 250, '₾130-250', 'Stepantsminda', 42.648, 44.638, 'Fine for confident kids; ask the stable about a minimum age or lead-rein option for younger riders.', true, ARRAY['kids', 'scenic']::TEXT[], 10, NULL, NULL),
  ('gudauri-kazbegi-rooms-restaurant', 'gudauri-kazbegi', 'Kazbegi Kitchen at Rooms Hotel', 'Georgian plates on a terrace framed by Kazbek and the Gergeti church — the region''s one genuine destination meal.', 'The restaurant at Rooms Hotel Kazbegi, a converted Soviet-era sanatorium turned design hotel, opens onto a floor-to-ceiling window wall and terrace facing Mount Kazbek and Gergeti Trinity Church across the valley — reason enough to book even before the food arrives. The kitchen runs a Georgian-leaning menu with a strong Georgian wine list, and pulls day-trippers as well as hotel guests, so it fills up at lunch and around sunset.', 'Recent reviews flag service as slow when the terrace is full — go for the view and pace yourself rather than expecting a quick meal. Reserve ahead in peak summer, especially for a terrace table at golden hour. Menu pricing below is approximate, built from limited review data rather than a published menu — confirm current prices on arrival. Reckon on ₾40-90 for a main course.', 'Golden hour, for the light on Kazbek', 90, '1.5 hr', 40, 90, '₾40-90', 'Stepantsminda', 42.658943, 44.65079, 'Full-service restaurant rather than a kid-focused spot, but staff are used to families passing through.', true, ARRAY['scenic', 'evening']::TEXT[], 11, NULL, NULL),
  ('gudauri-kazbegi-museum', 'gudauri-kazbegi', 'Stepantsminda History Museum', 'A small indoor museum on regional history and writer Alexander Kazbegi — the region''s real bad-weather fallback.', 'Housed in what was once a memorial house for 19th-century Georgian writer Alexander Kazbegi (after whom the town was long named), this compact museum mixes his personal effects with archaeological and ethnographic pieces from the wider Khevi region — old weapons, textiles, and photographs of the valley before the road existed. It''s a modest collection rather than a headline sight, but it''s the one genuinely indoor option in a region where weather closes the mountains often, and it gives useful context for what you''ve been driving past.', 'Closed Mondays; open roughly 10:00-18:00 other days. Some recent visitor reports mention irregular hours or temporary closures, so it''s worth confirming locally before making it your rain-day plan.', NULL, 40, '40 min', 1, 3, '₾3 adults, ₾1 students', 'Stepantsminda', 42.66068, 44.64328, 'Small and quiet rather than interactive — better suited to older kids with some patience.', false, ARRAY['cool']::TEXT[], 12, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Kakheti — 12 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Wine country',
  summary       = 'Georgia''s wine heartland: rolling vineyards along the Alazani valley, hilltop monasteries visible for miles, and family-run cellars where wine has been made in buried clay qvevri for 8,000 years. It rewards a slower pace than the mountains — plan a loop between Sighnaghi and Telavi rather than a single day trip from Tbilisi.',
  when_to_go    = 'April–June and September–October are best: mild days, green or gold vineyards, and (in autumn) the rtveli grape harvest, when family wineries let visitors help pick and tread grapes — book ahead, it''s the busiest season. July–August push 30–35°C in the Alazani valley, so do cellar visits and monastery walks in the morning or early evening and nap through midday. Winter is quiet and monasteries stay open, but days are short and some small family cellars close informally between tourist groups.',
  getting_there = 'From Tbilisi it''s about 1.5–2 hours to Sighnaghi via the newer Kakheti Highway through Sagarejo (well paved, fast), or roughly 2–2.5 hours to Telavi over the scenic but winding Gombori Pass. Both routes are fine in a normal car; only the last stretch to David Gareja needs a high-clearance vehicle or organized tour. Marshrutky (shared minibuses) run from Tbilisi''s Isani/Samgori station to Telavi and Sighnaghi, but a rental car or driver gives far more flexibility for hopping between wineries.',
  base_towns    = 'Sighnaghi (romantic hilltop old town, best for the walls, Bodbe, and dinner at Pheasant''s Tears) or Telavi (bigger, more central, best base for day trips to Tsinandali, Alaverdi, Ikalto, Gremi and the Kvareli-area cellars).'
WHERE id = 'kakheti';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('kakheti-sighnaghi-walls', 'kakheti', 'Sighnaghi Old Town Walls', 'Walk the ramparts of Georgia''s ''City of Love'' above an endless view of the Alazani valley.', 'Sighnaghi''s 18th-century defensive walls loop around the hilltop old town, with cobbled lanes, balconied houses, and watchtowers you can climb for a free panorama over the vineyards below toward the Caucasus. It''s an easy, mostly flat stroll connecting cafés, wine shops, and the town''s famous 24-hour wedding registry. Come at golden hour when the light hits the valley and the day-trip buses have thinned out.', 'Free and open at all hours; some rampart sections have unguarded drops, so keep an eye on small kids. Central streets are cobbled and steep in patches — fine for a stroller on the main square but not everywhere.', 'Late afternoon, for the light over the valley', 60, '1 hr', NULL, NULL, 'Free', 'Sighnaghi', 41.6205, 45.9167, 'Kids enjoy spotting the watchtowers and running the flatter stretches; nothing here needs supervision beyond normal wall-edge caution.', false, ARRAY['scenic', 'walk']::TEXT[], 1, NULL, NULL),
  ('kakheti-bodbe-monastery', 'kakheti', 'Bodbe Monastery of St. Nino', 'A working nunnery holding Georgia''s most venerated grave, with a cypress walk down to a holy spring.', 'Bodbe Convent, just outside Sighnaghi, holds the tomb of St. Nino, the woman credited with converting Georgia to Christianity in the 4th century — it''s one of the country''s most important pilgrimage sites. The cathedral and grounds are free to visit, and a path lined with cypress trees leads steeply down through forest to St. Nino''s spring, a popular (very cold) dip for the devout. Give the walk down and back at least 30 minutes on top of the church visit.', 'Strict dress code: women need a headscarf and skirt/wrap covering the knees (free wraps at the gate if you forget), men need long trousers. No photos or video inside the churches, and entry pauses during services. The path down to the spring is steep, uneven, and has no rail — supervise kids closely.', 'Morning, before tour groups arrive', 60, '1 hr', NULL, NULL, 'Free', 'Sighnaghi', 41.5998, 45.9033, 'The dress-code fuss and the request for quiet inside the church can be a lot for younger kids; the walk to the spring is the part they''ll actually enjoy.', false, ARRAY['scenic', 'walk']::TEXT[], 2, NULL, NULL),
  ('kakheti-alazani-viewpoint', 'kakheti', 'Alazani Valley Viewpoint Picnic', 'Pull off the Sighnaghi road for open space, a huge valley view, and a picnic with zero wine involved.', 'The road between Sighnaghi and Bodbe drops off the hilltop with wide, unbroken views across the Alazani valley''s vineyards toward the Caucasus — a natural spot to stop, spread a blanket, and let kids run without a tasting room or a church dress code in sight. Pick up bread, cheese, churchkhela, and fruit at a Sighnaghi shop or market stall beforehand. There''s no infrastructure here, which is the point: open grass, big sky, and a view worth lingering over.', 'No facilities, shade, or marked parking — bring water and a shade umbrella for midday. Treat it as a pull-off, not a ticketed site; exact best spots shift with roadworks.', 'Sunset', 40, '40 min', NULL, NULL, 'Free', 'Sighnaghi', 41.607, 45.905, 'The one stop on this list built entirely around kids having room to run around — no tasting, no church silence, no queue.', false, ARRAY['scenic', 'kids', 'walk']::TEXT[], 3, NULL, NULL),
  ('kakheti-pheasants-tears', 'kakheti', 'Pheasant''s Tears', 'Sighnaghi''s destination dinner: qvevri natural wine and a long Georgian table in a converted old-town house.', 'Pheasant''s Tears is a pioneer of Georgia''s natural-wine revival, run out of a rustic dining room and courtyard in Sighnaghi''s old town, pairing its own qvevri-made wines with a full spread of Georgian dishes — khinkali, lobio, badrijani, fresh bread from the on-site tone oven. It runs as a proper sit-down dinner rather than a quick tasting stop, with live music some evenings. Make it the anchor of an evening in Sighnaghi rather than a mid-day stop between sights.', 'Open daily 12:00–23:00 with the kitchen closing around 22:00. It''s popular with tour groups in summer — reserve ahead or arrive right at opening if you want to avoid a wait. Around ₾40-80 a head for dinner, and wine is charged on top.', 'Dinner', 90, '1.5 hr', 40, 80, '₾40-80', 'Sighnaghi', 41.6212, 45.9153, 'Kid-friendly menu overlap (bread, khinkali, cheese) but it''s a slow, multi-course dinner — better for kids used to sitting through a long meal than for very young ones past bedtime.', false, ARRAY['wine', 'evening']::TEXT[], 4, NULL, NULL),
  ('kakheti-tsinandali-estate', 'kakheti', 'Tsinandali Estate', 'The Chavchavadze family''s 19th-century manor and gardens, with a museum, old winery, and resort complex.', 'Tsinandali was the country estate of poet-nobleman Alexander Chavchavadze, whose 19th-century manor house, English-style dendrological park, and original stone winery now form a museum complex near Telavi. A guided visit takes you through period rooms and the old cellar (with a tasting option), followed by self-guided time in the gardens among cedars, magnolias, and peacocks. It''s the most polished, least rustic of the region''s wine stops — good for a first, easy introduction before the smaller family cellars.', 'Tickets: 5 ₾ (students), 10 ₾ (standard museum + old winery visit), 12 ₾ with a glass of wine included; under-6s free. There''s an on-site café/restaurant and a modern hotel complex next door.', 'Morning, before the day gets hot', 90, '1.5 hr', 5, 12, '₾5-12', 'Telavi', 41.8839, 45.4728, 'The gardens (and peacocks) are the real kid draw; the museum rooms and tasting room are a walk-through rather than hands-on, so budget more garden time than museum time for younger kids.', false, ARRAY['wine', 'scenic', 'kids']::TEXT[], 5, NULL, NULL),
  ('kakheti-alaverdi-cathedral', 'kakheti', 'Alaverdi Cathedral & Monastery', 'A working monastery under Georgia''s tallest historic cathedral, with monks still making wine in a 1,000-year-old cellar.', 'Alaverdi''s 11th-century cathedral rises over 50 meters — it was the tallest building in Georgia for nearly a thousand years — and stands alone in a walled compound surrounded by the monastery''s own vineyards. The monks continue a winemaking tradition that runs through a cellar dated to the 10th–12th centuries, and the grounds are quiet compared to the more touristed stops nearby. It''s as much a working religious community as a sight, so visits are respectful rather than rushed.', 'Free to enter; dress modestly (covered shoulders/knees) as at any active Georgian monastery. The cathedral can close to visitors during services, and whether the monastery''s own wine is available to taste or buy on a given day varies — ask on arrival rather than counting on it.', 'Morning', 45, '45 min', NULL, NULL, 'Free', 'Akhmeta', 42.0325, 45.377222, 'Mostly a look-and-walk stop for kids — the scale of the cathedral (Georgia''s tallest for centuries) is the thing worth pointing out to them.', false, ARRAY['scenic']::TEXT[], 6, NULL, NULL),
  ('kakheti-ikalto-academy', 'kakheti', 'Ikalto Monastery & Academy', 'Quiet ruins of Georgia''s first academy — where the poet Rustaveli reputedly studied — with almost nobody else there.', 'Ikalto is the stop most visitors skip in favor of Alaverdi, which is exactly its appeal: a 6th-century monastery complex with the roofless stone ruins of a 12th-century academy that once taught theology, philosophy, and winemaking alongside the sciences. A huge sunken winepress and rows of ancient qvevri sit among the ruins, a reminder that wine education was part of the curriculum. It''s a short, unstructured wander rather than a formal tour — good for a break between bigger stops without the crowds.', 'Free, no ticket booth or facilities on site. Ground is uneven stone rubble in places — watch footing, and bring water since there''s no shade to speak of.', NULL, 40, '40 min', NULL, NULL, 'Free', 'Telavi', 41.936944, 45.381111, 'Ruins kids can actually clamber around near (with supervision) rather than a hushed interior — a good antidote after the more formal Bodbe/Alaverdi stops.', false, ARRAY['scenic', 'walk']::TEXT[], 7, NULL, NULL),
  ('kakheti-twins-cellar', 'kakheti', 'Twins Wine Cellar', 'A small family qvevri cellar in Napareuli village — real working marani, not a tour-bus stop.', 'Twins Wine Cellar is run by twin brothers continuing their family''s Kakhetian-method winemaking in a cellar holding well over 100 buried qvevri, most sized to hold several tonnes of wine each. The hour-long visit walks through the vineyard, the working cellar, the tasting room, and even the small lab, ending with six to ten wines poured by the family themselves rather than a hired guide. It''s the most personal, least polished of the region''s wine stops — book ahead, as it runs on reserved slots rather than walk-in traffic.', 'Advance booking required, with a deposit taken ahead of the visit; open daily 11:00–19:00. Small groups only (roughly 3–15 people per session). Rural cellars like this typically prefer cash.', NULL, 60, '1 hr', 17, 17, '₾17', 'Napareuli / Telavi', 41.9111, 45.6072, 'Honest version: kids don''t taste and there isn''t a dedicated kids'' activity here, so it works best for kids old enough (roughly 8+) to sit through an hour of adult conversation and pouring — bring something to occupy younger ones.', true, ARRAY['wine']::TEXT[], 8, NULL, NULL),
  ('kakheti-khareba-tunnel', 'kakheti', 'Khareba Wine Tunnel', 'Taste inside 7.7 km of cool underground tunnels carved for Soviet-era wine storage near Kvareli.', 'Khareba ages and stores its wine in a network of hillside tunnels originally built for military use, now a constant, cellar-cool underground gallery you walk through on the way to the tasting room. Tours run from a basic tunnel walk-through with a short tasting up to fuller packages that add the viewing tower and a terrace restaurant with valley views. Because it''s underground, it''s naturally one of the best hot-day or bad-weather options in the region — the temperature barely moves whatever''s happening outside.', 'Open daily. Prices scale with the package — a simple tunnel-and-tasting visit runs well under the fuller food-and-workshop packages (see the separate family workshop listing). Book ahead in high season to avoid arriving alongside a big tour-bus group.', 'Morning, before tour-bus groups arrive', 90, '1.5 hr', 15, 30, '₾15-30', 'Kvareli', 41.933, 45.822, 'The tunnel itself is the kid highlight (cool, cave-like, a bit spooky in a fun way); ask for grape juice instead of wine at the tasting table rather than expecting them to sit it out.', false, ARRAY['wine', 'cool', 'kids']::TEXT[], 9, NULL, NULL),
  ('kakheti-khareba-kids', 'kakheti', 'Khareba Family Workshops', 'While the adults taste in the tunnel, kids bake bread, dip churchkhela, and (in harvest season) tread grapes barefoot.', 'Alongside its wine tunnel, Khareba''s touristic complex runs hands-on stations aimed squarely at families: baking Georgian bread in a tone oven, dipping churchkhela (the walnut-and-grape-must candle-shaped candy), and watching or joining a chacha distillation demo. During the September–October rtveli harvest, the highlight is treading grapes barefoot in a satsnakheli, the traditional wooden press, alongside seasonal grape picking. It''s the honest answer to ''what do the kids do'' during the adults'' tasting next door.', 'Arrange this alongside your tunnel/tasting booking rather than expecting to walk in and join — the fuller package (workshops plus a cooked meal) runs well above a bare tunnel visit. Grape treading is seasonal (roughly September–October); confirm what''s actually running when you book outside harvest time.', NULL, 60, '1 hr', 30, 55, '₾30-55', 'Kvareli', 41.9325, 45.8228, 'This is the purely-for-kids stop on the list — no tasting room, no dress code, no sitting still.', true, ARRAY['kids', 'cool']::TEXT[], 10, NULL, NULL),
  ('kakheti-gremi', 'kakheti', 'Gremi Royal Church & Tower', 'Climb the bell tower of a 16th-century royal capital for a wraparound view of the Alazani valley.', 'Gremi was the capital of the Kingdom of Kakheti until a Persian invasion destroyed it in 1615; what survives is the domed Church of the Archangels, a three-story royal tower you can climb, defensive walls, and a small museum of medieval artifacts inside the tower itself. The climb up narrow stone stairs to the bell level is the main event for most kids, rewarded with an open view over the vineyards and hills. It''s a compact, quick stop that pairs naturally with a Kvareli-area wine day.', 'Entry 10 ₾; open roughly 10:00–17:00, though hours can shift off-season — worth confirming same-day if visiting late afternoon. The tower stairs are steep and narrow.', NULL, 60, '1 hr', 10, 10, '₾10', 'Kvareli', 42.001944, 45.66, 'The tower climb is the draw — steep, narrow stairs that most kids find genuinely exciting rather than a chore.', false, ARRAY['scenic', 'walk', 'kids']::TEXT[], 11, NULL, NULL),
  ('kakheti-david-gareja', 'kakheti', 'David Gareja Monastery Complex', 'A remote cave-monastery cut into a semi-desert ridge, with a hike to frescoes right on the Azerbaijan border.', 'David Gareja is a sprawling complex of monasteries carved into a dry, canyon-like ridge on Georgia''s semi-desert eastern edge, founded in the 6th century and still home to a small community of monks. The main Lavra monastery is a fairly easy walk from the parking area, but the famous frescoes at the Udabno complex require a steeper, exposed uphill hike along the ridge — with genuinely no shade. It''s the most remote and least polished stop on this list, worth the detour for the landscape alone but best treated as a half-day commitment once driving time is added.', 'Free entry (donations welcome); the final approach road is rough and best done in a high-clearance vehicle or with an organized tour, especially after rain. Go early to avoid the brutal midday heat on the exposed hike. The Udabno fresco complex sits directly on the disputed Georgia–Azerbaijan border and access there has been periodically restricted — check current status with a local guide or tour operator before counting on seeing it.', 'Spring or autumn morning', 150, '2.5 hr', NULL, NULL, 'Free', 'Sagarejo', 41.454444, 45.356667, 'The Lavra monastery itself is manageable for most kids; the steep, shadeless climb to the Udabno frescoes is a real hike better suited to kids roughly 8+ who can handle heat and exposure.', false, ARRAY['cave', 'hike', 'scenic']::TEXT[], 12, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Kutaisi & Imereti — 12 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Caves, canyons & water',
  summary       = 'Georgia''s second city and its western hinterland: lit stalactite caves, a cliffside canyon walkway, turquoise canoe water, and two UNESCO-era monasteries within a short drive of each other. Kutaisi itself adds an old-town evening of a river bridge, a gilded fountain, and one of the best tables in the west. Note that Martvili Canyon — the classic pairing with a Kutaisi day trip — actually sits over the border in Samegrelo; it''s included here because that''s how virtually everyone visits it, not because it''s geographically Imereti.',
  when_to_go    = 'Genuinely year-round — Prometheus Cave and Sataplia are open daily, indoors, and cool, making them the region''s answer to both summer heat and rain. Okatse''s hanging walkway and Martvili''s canyon path close outright in rain or snow for safety, so build a backup day if you''re visiting outside the reliable April-October season. Kinchkha and Okatse are shoulder-season prettiest in spring when the rivers run fuller. Avoid assuming a Monday closure here — unlike many Georgian sites, Prometheus, Sataplia and Okatse are all open seven days a week.',
  getting_there = 'Kutaisi is 220-240 km from Tbilisi, 4-4.5 hours by car on the E60/S1 highway (good tarmac throughout, including the Rikoti Pass tunnel corridor). A daily fast train covers the same route in about 5 hours; marshrutkas run regularly from Tbilisi''s Didube station (~4.5 hr). Kutaisi International Airport also has direct low-cost flights from several European cities, which makes this region a common start or end point for a wider Georgia loop rather than a pure day trip from Tbilisi. Once in the region, the canyon and cave sites are 30-70 minutes apart by car in different directions — a rented car or driver is the practical way to link more than one or two in a day.',
  base_towns    = 'Kutaisi is the obvious base — central to everything here, with the widest range of hotels and restaurants, and close enough to Gelati, Motsameta and Bagrati to visit on foot or a short taxi ride. Plan on two nights if you want to cover the caves/canyons axis (Prometheus, Sataplia, Okatse, Kinchkha), the Martvili detour, and the monasteries without rushing any of them.'
WHERE id = 'kutaisi-imereti';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('kutaisi-imereti-prometheus-cave', 'kutaisi-imereti', 'Prometheus Cave', 'A 1.4km lit stalactite gallery through six chambers, ending in an optional underground boat ride.', 'Prometheus (Kumistavi) Cave is one of Georgia''s largest show caves, with a paved, lit 1.4 km walking route through six of its many chambers, past stalactites, stalagmites, and small underground pools, with classical music piped in along the way. A guide (included in the ticket) walks the group through and explains the formations. At the far end, an optional boat ride floats you roughly 280 m along the underground river back toward the exit — genuinely atmospheric, though short. The boat is suspended after heavy rain when the river runs high, so it isn''t guaranteed even if you pay for it.', 'Open every day of the year, no closing day. The boat is a separate ticket on top of entrance and is sometimes cancelled after rain — ask at the ticket counter before paying for it. Ticket price includes a Georgian/English/Russian-speaking guide.', NULL, 120, '2 hr', 40, 70, '₾40-70', 'Tsqaltubo', 42.376641, 42.600845, 'Cool, flat, and lit throughout — an easy win for kids, and the boat ride at the end feels like a mini theme-park moment.', false, ARRAY['cave', 'cool', 'kids', 'scenic']::TEXT[], 1, NULL, NULL),
  ('kutaisi-imereti-sataplia', 'kutaisi-imereti', 'Sataplia Nature Reserve', 'Real Cretaceous dinosaur footprints under glass, a short cave, and a glass panoramic platform over Imereti.', 'Sataplia protects a set of genuine dinosaur tracks preserved in limestone, displayed under a protective pavilion as the reserve''s headline attraction. From there a guided loop leads through a small karst cave with colored lighting, a stretch of relict Colchic forest, and out to a glass-floored panoramic terrace looking over the Kutaisi lowlands. It''s compact and entirely guided — you can''t wander off-route — which keeps the whole visit tight and family-friendly.', 'Open every day, 10:00-17:00, no closing day — the panoramic walkway simply closes in rain or snow for safety. Foreign-adult tickets run well above the resident rate; bring ID if you qualify for the local price. Children aged 6-18 pay ₾5.50, and under-6s are free.', NULL, 75, '1 hr 15 min', 30, 30, '₾30', 'Kutaisi', 42.316167, 42.672667, 'The dinosaur footprints are the highlight for young kids — genuine tracks under glass, not replicas.', false, ARRAY['cave', 'kids', 'scenic']::TEXT[], 2, NULL, NULL),
  ('kutaisi-imereti-okatse-canyon', 'kutaisi-imereti', 'Okatse Canyon', 'A steel walkway clipped to a cliff face, 100m above a river gorge, in Khoni''s Dadiani forest.', 'Okatse''s hanging trail is a 780 m steel walkway bolted directly into the canyon wall, with sections of mesh or glass flooring so you''re looking straight down into the gorge. Getting there is part of the visit: it''s roughly 2.3 km from the visitor centre through forest to the trailhead, walkable or covered by a shuttle van for a fee. Reviewers regularly compare the exposure and drop to something out of an adventure film — genuinely dramatic rather than a token viewpoint.', 'Budget for the approach walk, not just the walkway itself — most of the visit is the 2.3 km each-way trail through the forest before you even reach the hanging section. Closed to walkers outright in rain or snow. Entrance is ₾20 for foreigners (₾12 residents); the shuttle van is a separate, informally-priced service — confirm the fare on arrival rather than assuming a number. Children aged 6-18 pay ₾5.50.', 'Morning, before tour groups arrive from Kutaisi', 150, '2.5 hr', 20, 20, '₾20', 'Gordi', 42.451306, 42.550056, 'Thrilling but genuinely exposed on a mesh/glass walkway high above the gorge — good for confident kids, not toddlers or anyone uneasy with heights.', false, ARRAY['cave', 'hike', 'scenic']::TEXT[], 3, NULL, NULL),
  ('kutaisi-imereti-kinchkha-waterfall', 'kutaisi-imereti', 'Kinchkha Waterfall', 'A three-tier, 130m cascade reached by a quiet forest trail most Kutaisi day-trippers skip entirely.', 'Kinchkha (also called Okatse Waterfall) drops in three stages — roughly 25 m, 70 m, and 35 m — down a forested valley near Okatse Canyon, in the same Khoni municipality. A marked ~2.1 km trail from Kinchkha village leads to the viewing point; it sees a fraction of Okatse''s crowds despite sitting close by. This is the region''s clearest "most visitors miss it" stop — worth the extra detour if you already have a driver out this way.', 'No entrance fee currently. It''s near Okatse but is a separate stop with its own trailhead and parking, not a shared ticket — plan the extra time rather than assuming a quick add-on. The forest path gets muddy after rain, so wear real shoes.', NULL, 90, '1.5 hr', NULL, NULL, 'Free', 'Khoni', 42.495639, 42.550528, 'The walk is longer and less built-up than Okatse''s — fine for kids who like a forest hike, less practical with a stroller.', false, ARRAY['water', 'walk', 'scenic']::TEXT[], 4, NULL, NULL),
  ('kutaisi-imereti-martvili-canyon', 'kutaisi-imereti', 'Martvili Canyon', 'A narrow limestone gorge with water so turquoise it looks dyed, floated by canoe past mossy cliffs.', 'Martvili''s canyon walk follows a walkway along the rim and floor of a narrow gorge cut by the Abasha River, past small waterfalls and pools of striking turquoise-green water. The highlight is the roughly 20-minute canoe/boat section through the most dramatic stretch of the gorge — the walking loop alone is short and most people are really here for the water. Technically this sits in Samegrelo, not Imereti, about 1-1.5 hours from Kutaisi, but it''s included here because it''s the day trip virtually every Kutaisi-based visitor actually takes, usually paired with Prometheus Cave or Okatse.', 'Geography note: Martvili is in Samegrelo region, not Imereti — don''t be surprised if other sources file it separately. Open 10:00-18:00 (summer, last entry 17:30); winter hours start later. The boat/canoe ride is a separate ~₾20 add-on and can queue up badly in summer; a separately-operated zipline (₾50-100) is available too.', 'Weekday morning, before tour buses arrive', 90, '1.5 hr', 20, 40, '₾20-40', 'Martvili', 42.45856, 42.37752, 'The canoe section is calm, life-jacketed water — a highlight for kids, though the boat queue can run long in peak summer.', false, ARRAY['cave', 'water', 'scenic', 'kids']::TEXT[], 5, NULL, NULL),
  ('kutaisi-imereti-gelati-monastery', 'kutaisi-imereti', 'Gelati Monastery', 'King David the Builder''s 12th-century monastery and academy — still on the UNESCO list, still under scaffolding.', 'Founded in 1106 by David IV, Gelati was both a monastery and one of the era''s great centers of learning, and its main cathedral holds a celebrated 12th-century mosaic of the Virgin along with extensive frescoes. Unlike Bagrati Cathedral in town, Gelati remains on UNESCO''s World Heritage list. It is, however, in the middle of a long-running restoration: parts of the main church''s facade and interior are behind scaffolding, though the apse mosaic and most frescoes remain visible. The complex also includes smaller churches and King David''s own tomb at the gate, by tradition placed so visitors would walk over it.', 'Free entry, open daily (roughly 9am-7pm, though hours have been reported as inconsistent during restoration work). Expect scaffolding on parts of the main cathedral — it doesn''t block the mosaic or most frescoes, but it does affect photos. Modest dress required as at any active church.', 'Morning, paired with Motsameta on the same road', 50, '50 min', NULL, NULL, 'Free', 'Kutaisi', 42.29472, 42.76806, NULL, false, ARRAY['scenic', 'walk']::TEXT[], 6, NULL, NULL),
  ('kutaisi-imereti-motsameta-monastery', 'kutaisi-imereti', 'Motsameta Monastery', 'A cliff-edge monastery over the Tskaltsitela gorge, where locals crawl under a martyrs'' shrine for luck.', 'Motsameta sits on a dramatic promontory above a bend in the Tskaltsitela (''Red Water'') river, named for two 8th-century Georgian dukes martyred here by Arab invaders. Inside, the ark holding their relics sits on a raised platform; local tradition holds that circling it three times and ducking under a low tunnel beneath it — without touching the walls or ceiling — grants a wish. It gets a fraction of Gelati''s visitors despite being only a few minutes down the same road, and the canyon-edge setting is arguably the more striking view of the two.', 'Free entry, open roughly 8am-8pm daily. Most day trips skip it in favor of Gelati next door — that''s exactly what makes it the quieter of the two.', NULL, 30, '30 min', NULL, NULL, 'Free', 'Kutaisi', 42.28194, 42.75917, 'The crawl-under-the-shrine tradition is a fun, harmless bit of ritual for kids to try.', false, ARRAY['scenic', 'walk']::TEXT[], 7, NULL, NULL),
  ('kutaisi-imereti-bagrati-cathedral', 'kutaisi-imereti', 'Bagrati Cathedral', 'An 11th-century cathedral rebuilt so completely in 2012 that it cost Georgia its UNESCO listing.', 'Bagrati crowns a hill over central Kutaisi and the Rioni River, and remains an active cathedral — seat of the Metropolitan of Kutaisi and a popular local wedding venue. Its full-scale reconstruction, completed in 2012 after the medieval structure stood largely as a ruin for centuries, was judged by UNESCO to have compromised its authenticity so severely that the site was permanently removed from the World Heritage list in 2017; unlike neighboring Gelati, it has not been relisted. Visit for the hilltop view over the city and river rather than for original medieval fabric — most of what stands today is 21st-century reconstruction.', 'Free entry. It''s a working cathedral, so modest dress and quiet are expected, especially on weekends when weddings are common. Worth knowing before you go: this is a reconstruction, not the original 11th-century building.', 'Golden hour, for the view over the Rioni', 30, '30 min', NULL, NULL, 'Free', 'Kutaisi', 42.2773, 42.7043, NULL, false, ARRAY['scenic', 'walk']::TEXT[], 8, NULL, NULL),
  ('kutaisi-imereti-katskhi-pillar', 'kutaisi-imereti', 'Katskhi Pillar', 'A tiny monastery perched atop a 40m limestone pillar, viewable only from the ground since climbing was restricted.', 'Near Chiatura, a single limestone pillar rises about 40 m from the valley floor, topped by a small church that a resident monk has occupied since the 1990s. Climbing the pillar has been restricted to the monk and clergy since 2018 — visitors cannot go up, even on a guided basis. What you actually do here is view the pillar from the base church of Simeon Stylites and the surrounding cave complex at ground level; the strange silhouette against the sky is the whole point, not an ascent.', 'You cannot climb the pillar or visit the summit chapel under any circumstances — that''s monks-only. Everything visitable is at ground level: the base church and nearby caves. It''s roughly 1.5-2 hours from Kutaisi via Chiatura, whose old Soviet cable cars are worth a stop in their own right if you''re already out this way.', NULL, 45, '45 min', NULL, NULL, 'Free', 'Chiatura', 42.2875, 43.2156, 'No climbing involved for visitors, so it''s an easy stop — the appeal for kids is mostly the ''how do the monks even live up there'' story.', false, ARRAY['scenic', 'walk']::TEXT[], 9, NULL, NULL),
  ('kutaisi-imereti-old-town', 'kutaisi-imereti', 'Kutaisi Old Town: White Bridge & Colchis Fountain', 'An evening stroll over the Rioni''s pedestrian White Bridge, ending at a fountain of gilded Colchian animals.', 'Kutaisi''s White Bridge is a pedestrian crossing over the Rioni River linking the old town to the riverside promenade, lined with cafes that fill up as the evening cools. A short walk away, Colchis Fountain in the central square is decorated with gilded replicas of the animal and figurine motifs from the region''s famous Colchian gold hoards, lit up after dark. Neither site takes long individually, but together with the surrounding lanes they make the natural place to end a day out at the canyons and caves.', 'Free to wander. Best after sunset, when both the bridge and the fountain are lit — daytime is fine but doesn''t show off either landmark as well.', 'Evening, after dinner', 60, '1 hr', NULL, NULL, 'Free', 'Kutaisi', 42.268748, 42.700381, 'Flat, pedestrian-only, and lively in the evening — easy with kids in tow, with ice cream stalls along the way.', false, ARRAY['walk', 'evening', 'kids']::TEXT[], 10, NULL, NULL),
  ('kutaisi-imereti-palaty', 'kutaisi-imereti', 'Palaty', 'A two-floor old-town institution serving clay-pot pelmeni, walnut-and-pomegranate kuchmachi, and the city''s best lobiani.', 'Tucked behind an easy-to-miss doorway near the White Bridge, Palaty is a longstanding Kutaisi favorite that doubles as a wine bar with a solid list of Georgian ambers and reds. The ground floor has a romantic, sometimes live-jazz atmosphere; upstairs is brighter and more casual. Order the Siberian-style pelmeni baked and sealed in a clay pot, the kuchmachi (liver and heart with walnuts and pomegranate), and the Imeretian lobiani — regularly cited as the best bean bread in the city — alongside an Adjarian khachapuri to share.', 'The entrance is genuinely easy to miss — look for the wood doorway under the arches near the White Bridge and follow the stairs up to the dining floors. It draws both locals and tour groups, so reserve ahead for dinner in high season if you can.', 'Dinner, or lunch to beat the evening crowd', 90, '1.5 hr', 30, 60, '₾30-60 per person', 'Kutaisi', 42.268896, 42.702041, 'Big shareable plates and a relaxed two-floor layout suit kids fine, though the ground-floor live-jazz nights skew toward an adult evening vibe.', false, ARRAY['wine', 'evening']::TEXT[], 11, NULL, NULL),
  ('kutaisi-imereti-baias-wine', 'kutaisi-imereti', 'Baia''s Wine', 'A family qvevri winery in the Imereti hills where the tasting comes with a full home-cooked Imeretian meal.', 'Run by siblings Baia, Gvantsa, and Giorgi Abuladze in the village of Meore Obcha near Baghdati, Baia''s Wine is a small, low-intervention winery working with indigenous Imereti grapes — Tsitska, Tsolikouri, Krakhuna, Otskhanuri Sapere, and Aladasturi — fermented in traditional qvevri. A visit is a guided walk through the vineyard and cellar with the family, followed by a seated tasting of several qvevri wines, often paired with home-cooked Imeretian food. Everything happens indoors or under cover once you''re past the vineyard walk, which makes it the region''s best rainy-day pivot once you''ve had your fill of the show caves.', 'This is a small family operation that runs on advance booking — don''t plan on walking in. Tasting-only is roughly ₾70 per adult (₾40 for children under 12); the fuller wine-and-dine experience with a home-cooked meal costs more and is often booked as a package with transport included, so confirm the exact price and what''s included when you book.', 'Lunch or early afternoon', 150, '2.5 hr', 40, 70, '₾40-70', 'Baghdati', 42.123031, 42.896887, 'A working winery visit, not built for kids — the cellar walk and seated tasting run long for younger children.', true, ARRAY['wine', 'cool']::TEXT[], 12, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Mtskheta & the Military Highway — 10 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Ancient capital, the road north',
  summary       = 'Georgia''s ancient capital and spiritual center, just 20 minutes from Tbilisi, paired with the opening stretch of the Georgian Military Highway as it follows the Aragvi River north to the turquoise Zhinvali reservoir and Ananuri fortress. Two UNESCO cathedrals sit alongside a quieter cave-monastery, a genuine destination meal, and a paddle or raft on the water. This is a full, satisfying day (or two) without committing to the longer push toward Gudauri and Kazbegi.',
  when_to_go    = 'Year-round — unlike the high passes further north, this lower stretch rarely closes for weather. In summer, aim to be inside Jvari or Svetitskhoveli before 10am to beat both the heat and the tour-bus crush. Water activities (rafting and kayaking) run roughly mid-April through mid-October only, so check dates if visiting outside summer.',
  getting_there = 'Mtskheta is 20-25 min (~20 km) from Tbilisi via the Mtskheta Highway (S1), on good tarmac the whole way. Ananuri and the Zhinvali reservoir add another 40-45 min further north on the paved, well-maintained Georgian Military Highway (E117) — no 4x4 needed for this segment. Marshrutkas run from Tbilisi''s Didube station to Mtskheta (~30 min, a couple of GEL); getting on to Ananuri or Zhinvali by public transport is thin, so a car, taxi, or organized tour is the practical option.',
  base_towns    = 'Almost everyone day-trips from Tbilisi — it''s genuinely close enough that basing here isn''t necessary. Mtskheta itself has a handful of small guesthouses if you''d rather overnight, which buys you an early start before the tour buses arrive at Jvari and Svetitskhoveli.'
WHERE id = 'mtskheta';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('mtskheta-old-town', 'mtskheta', 'Mtskheta Old Town Wander', 'Cobbled lanes, churchkhela stalls, and the river confluence Georgians consider sacred ground.', 'Wander the pedestrianized lanes around Svetitskhoveli, lined with wine cellars, souvenir stalls, and outdoor cafes selling churchkhela. Head down toward the riverbank for a look at where the Aragvi meets the Mtkvari (Kura) — the same confluence you''ll see from above at Jvari. It''s flat, partly shaded, and the closest thing to a relaxed stroll-and-snack break in the region.', 'Free to wander; parking fills by mid-morning in high season, so arrive early or plan for a short walk in from a lot.', 'Late afternoon, after the day-trip buses have left', 45, '45 min', NULL, NULL, 'Free', 'Mtskheta', 41.845, 44.7185, 'Flat and easy for little legs, with plenty of ice cream and churchkhela stalls to bribe with.', false, ARRAY['walk', 'kids']::TEXT[], 1, NULL, NULL),
  ('mtskheta-svetitskhoveli', 'mtskheta', 'Svetitskhoveli Cathedral', 'Georgia''s holiest cathedral, said to hold Christ''s robe, and still the seat of the Georgian church.', 'This 11th-century UNESCO-listed cathedral is the spiritual heart of the Georgian Orthodox Church, built on the site where, legend holds, Christ''s robe was buried. Step inside for the soaring stone interior, faded frescoes, and royal tombs, including several Bagrationi kings. The walled courtyard around it is part of the same complex and worth a slow circuit. It''s a working church, so expect services, incense, and the occasional wedding or baptism in progress.', 'Cover shoulders and knees — wraps are usually available to borrow at the door. Busiest 11am-2pm with tour groups; go before 10am or after 4pm. Free, but donations are welcomed.', 'Before 10am, or after 4pm', 40, '40 min', NULL, NULL, 'Free', 'Mtskheta', 41.8455, 44.7191, 'Interesting even for kids who normally balk at churches — giant stone pillars, royal tombs, and a carved dragon fresco give you things to point at.', false, ARRAY['scenic', 'walk']::TEXT[], 2, NULL, NULL),
  ('mtskheta-samtavro', 'mtskheta', 'Samtavro Convent', 'A quieter 4th-century convent two minutes from the cathedral, where Georgia''s first Christian king is buried.', 'Samtavro traces back to where St. Nino lived after bringing Christianity to Georgia in the 4th century, but sits just a few minutes'' walk from Svetitskhoveli and gets a fraction of the visitors. Inside the walled complex are the 11th-century Transfiguration Church, a smaller church of St. Nino, and the graves of King Mirian and Queen Nana, Georgia''s first Christian royals. It''s a working convent — nuns tend the grounds — and noticeably calmer than the main cathedral next door. A good option when Svetitskhoveli feels overrun with tour groups.', 'Free entry; modest dress expected as at any active church. It''s the site most visitors miss rather than the reverse — worth the extra 20 minutes if you have them.', NULL, 20, '20 min', NULL, NULL, 'Free', 'Mtskheta', 41.8479, 44.7201, NULL, false, ARRAY['walk']::TEXT[], 3, NULL, NULL),
  ('mtskheta-jvari', 'mtskheta', 'Jvari Monastery', 'Hilltop monastery framing Georgia''s most photographed view: two rivers meeting far below.', 'Perched on a ridge above the confluence of the Mtkvari and Aragvi rivers, this 6th-century monastery is one of Georgia''s oldest surviving churches and the view behind half its postcards. The small stone church itself takes only a few minutes to see; the real draw is the panorama over Mtskheta and the valley. It gets crowded with tour buses by mid-morning, and the single viewpoint bottlenecks fast. Go early or at golden hour for better light and more room to breathe.', 'Free; no shade at the viewpoint, so bring hats and water in summer. Modest dress required inside the church. Tour buses arrive from around 10:30am onward.', 'Before 10am, or golden hour', 30, '30 min', NULL, NULL, 'Free', 'Mtskheta', 41.8383, 44.7331, 'The view is the payoff, not the church interior — good for restless kids who''d rather be outside than in another cathedral.', false, ARRAY['scenic']::TEXT[], 4, NULL, NULL),
  ('mtskheta-shio-mgvime', 'mtskheta', 'Shio-Mgvime Monastery', 'A cave-monastery tucked into a limestone canyon that most day-trippers never find.', 'Founded in the 6th century by the monk Shio, who lived as a hermit in a cave here, this monastery sits in a narrow, dramatic canyon about 8 km from Mtskheta and sees a fraction of Jvari''s crowds. Wander the terraced complex, peer into Shio''s original cave cell, and follow the path up the canyon wall for a quiet valley view. Monks and nuns still live and work the grounds, so keep voices down. The unpaved access road is fine for a normal car taken slowly.', 'No entrance fee (donations welcome); modest dress required, including headscarves for women. No cafe on site — bring water. It''s an active monastic community, not a signposted tourist site, so visits should stay quiet.', 'Morning', 50, '50 min', NULL, NULL, 'Free', 'Mtskheta', 41.8625, 44.6403, 'The cave cell and canyon setting tend to land better with kids than another cathedral interior — frame it as a monk''s hideout.', false, ARRAY['cave', 'scenic', 'walk']::TEXT[], 5, NULL, NULL),
  ('mtskheta-mukhrani', 'mtskheta', 'Chateau Mukhrani', 'A restored royal winery estate with underground cellars and a proper indoor restaurant.', 'Chateau Mukhrani is a restored 19th-century estate of the Bagrationi-Mukhrani royal family, about 20 minutes from Mtskheta, built in a French-chateau style with formal gardens and a working winery beneath it. Walk the grounds for free, or take the short guided tour through the underground cellar, finishing with a tasting of four estate wines. The on-site restaurant serves a full Georgian menu indoors, making this the region''s best fallback when the weather turns. Book the tasting ahead in peak season; the grounds and restaurant don''t need reservations.', 'Grounds are free to walk; the cellar tour plus tasting runs roughly ₾35 per person. Book the tasting slot ahead on weekends. Restaurant and cellar are fully indoor/covered — a genuine wet-weather option.', 'Late morning or lunchtime', 90, '1.5 hr', 15, 35, '₾15-35', 'Mukhrani', 41.942, 44.5814, 'Grounds and gardens are easy for kids to run around; the cellar tasting is an adult interest, but the restaurant has kid-friendly Georgian staples.', true, ARRAY['wine', 'cool', 'kids']::TEXT[], 6, NULL, NULL),
  ('mtskheta-salobie-bode', 'mtskheta', 'Salobie Bode', 'Clay-pot bean stew (lobio) that locals and every guidebook agree is the best in the country.', 'Salobie Bode has been serving lobio — beans slow-baked in individual clay pots with cornbread (mchadi) — since long before Mtskheta was a tourist stop, and it''s still the reason to eat here rather than just refuel. Portions are enormous, prices are low, and the beer-garden-style outdoor seating fills with as many locals as visitors. Order the lobio, a plate of khinkali, and mtsvadi (grilled meat) to share family-style. It sits just south of the old town on the way in or out of Mtskheta, so it''s an easy detour rather than a special trip.', 'Cash is the safe bet — card acceptance is inconsistent. Busy at lunch on weekends; arrive by 12:30 to beat the rush. Seating is outdoor with limited shelter, so pair a rainy day with Chateau Mukhrani instead.', 'Lunchtime, before 1pm', 60, '1 hr', 20, 30, '₾20-30 per person', 'Mtskheta', 41.8285, 44.72529, 'Big shareable portions and a relaxed, noisy atmosphere — no need for quiet-restaurant behavior.', false, ARRAY['wine']::TEXT[], 7, NULL, NULL),
  ('mtskheta-zhinvali-kayak', 'mtskheta', 'Zhinvali Reservoir Kayaking', 'Calm, swimmable turquoise water on the Zhinvali reservoir — the region''s easiest cool-off.', 'The Aragvi Adventure Center, on the wooded bank where the Pshavis Aragvi river meets the Zhinvali reservoir, rents kayaks and canoes for a gentle paddle on genuinely turquoise, swimmable water. It''s calm rather than technical — a good fit for nervous paddlers or younger kids who''d find the rafting a step too far. The center also has a playground, volleyball court, and a short zipline if the water alone isn''t enough. It only operates mid-April through mid-October, so this isn''t a shoulder-season option.', 'Open mid-April to mid-October only — confirm before planning an off-season visit. Confirm the current rental price on arrival; rates are set by the operator and can shift season to season. Bring a change of clothes.', 'Midday, when the water is warmest', 120, '2 hr', 40, 60, '₾40-60', 'Zhinvali', 42.2205, 44.8321, 'The calmest water option in the region — swimmable, shallow near the bank, and life jackets provided.', false, ARRAY['water', 'kids', 'cool']::TEXT[], 8, NULL, NULL),
  ('mtskheta-aragvi-rafting', 'mtskheta', 'Aragvi River Rafting', 'A gentle grade II-III float down the Aragvi — thrilling for kids without scaring the grown-ups.', 'The same Aragvi Adventure Center runs half-day rafting trips on the Aragvi, with certified guides, life jackets, and helmets included. Water is highest and roughest (grade III-IV) during May-June snowmelt; by August and September it settles to a family-friendly grade II, the sweet spot for this itinerary. Trips typically run 1.5-2 hours on the water in a 6-8 seat raft, often paired with a riverside barbecue lunch. It only runs mid-April through mid-October, so check dates if traveling outside summer.', 'Runs mid-April to mid-October only. Book ahead for peak summer weekends. Most operators set a minimum age (commonly around 8-10) — confirm this when booking if traveling with younger kids. Bring a dry bag for phones and cash. Operators meet you at their own base on the Aragvi; confirm the exact put-in when you book.', 'Late summer (Aug-Sep), when the river is calmest', 150, '2.5 hr', 120, 180, '₾120-180 per person', 'Zhinvali', NULL, NULL, 'Genuinely thrilling for kids but graded gentle by August; check the operator''s minimum age before booking.', true, ARRAY['water', 'thrill', 'kids']::TEXT[], 9, NULL, NULL),
  ('mtskheta-ananuri', 'mtskheta', 'Ananuri Fortress', 'A 17th-century fortress-church complex rising straight out of the turquoise Zhinvali reservoir.', 'Ananuri''s stone towers and twin churches sit directly on the reservoir shore, making it one of the most photographed stops on the Military Highway. Climb the fortress walls and tower for a view over the water, then step inside the churches to see the carved stone facades and frescoed interiors. The complex is compact, but the climbing — steep, uneven stone stairs, low doorways — makes it more physical than the free churches back in Mtskheta. Food stalls and viewpoint pull-offs line the road just outside, good for a snack or photo before continuing north.', 'Free entry; modest dress for the churches. Stairs inside the towers are steep, uneven, and unguarded in places — supervise kids and wear real shoes, not sandals. Gets crowded with tour buses at midday.', 'Morning or golden hour', 45, '45 min', NULL, NULL, 'Free', 'Ananuri', 42.1633, 44.6967, 'Kids love climbing the tower, but the stairs are steep and unguarded in places — hold hands on the way down.', false, ARRAY['scenic', 'water', 'walk']::TEXT[], 10, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Samtskhe-Javakheti — 10 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Vardzia cave city & Rabati fortress',
  summary       = 'Samtskhe-Javakheti is Georgia''s southern borderland with Turkey and Armenia, where an Ottoman-restored fortress, a cliffside cave city, and a wind-scoured volcanic plateau sit within one long day''s drive of each other. Akhaltsikhe''s Rabati Fortress and the forest monastery at Sapara anchor the region''s north, Khertvisi and Vardzia its dramatic river-carved south, and the astronomical observatory and sulfur baths of Abastumani a quieter, cooler detour to the west. Furthest out, the Javakheti plateau''s lakes and the exiled Doukhobor community''s museum near Ninotsminda are a genuinely remote add-on, not a casual stop. Plan on two to three days to do the region justice rather than a single rushed loop from Tbilisi.',
  when_to_go    = 'May through September is the safe window for the whole region — Akhaltsikhe, Sapara, Khertvisi and Vardzia are pleasant through this stretch, with July-August bringing real heat at Vardzia''s exposed cliff sections. The Javakheti plateau around Ninotsminda is a different climate entirely: even summer days carry a biting wind, guesthouses commonly lack bedroom heating, and the high lakes freeze over in winter with roads liable to snow closure — treat a plateau visit as a fair-weather, daylight-hours excursion only, and avoid it altogether from late autumn to spring unless you have real cold-weather gear and a 4x4. Abastumani''s night observatory tours run only in summer months.',
  getting_there = 'Akhaltsikhe is about 200 km (roughly 3 hours) from Tbilisi on a good, mostly modern highway via Gori — no 4x4 required. Vardzia adds another 60 km beyond Akhaltsikhe (3.5-4 hours total from Tbilisi one-way); the road narrows and roughens past Akhaltsikhe, with occasional rough patches, though it stays passable for an ordinary car. Marshrutkas run Tbilisi-Borjomi-Akhaltsikhe-Vardzia in stages, but connections are infrequent enough that public transport really only works as a two-day trip with an overnight en route. The Javakheti plateau around Ninotsminda is a further, separate push southeast from Akhaltsikhe on high, exposed roads — budget extra time, expect worse surfaces, and don''t attempt it in poor weather or winter.',
  base_towns    = 'Akhaltsikhe is the practical base for Rabati, Sapara, Khertvisi and Vardzia — it has the region''s best range of guesthouses and hotels and sits closest to all four. Abastumani, about 25 km away, is worth an overnight in its own right if the observatory or sulfur baths are a priority. Ninotsminda has basic guesthouses if you''re pushing on to the Javakheti plateau, but heating and amenities are limited — most visitors day-trip the plateau from Akhaltsikhe instead of overnighting on it.'
WHERE id = 'samtskhe-javakheti';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('samtskhe-javakheti-rabati', 'samtskhe-javakheti', 'Rabati Fortress', 'A restored Ottoman-Georgian fortress where a mosque, a church and a citadel share one walled complex.', 'Akhaltsikhe''s Rabati Fortress is a fully restored 9th-13th century complex reworked under Ottoman rule, with a free lower town of shops, a vineyard and cafes open to wander any time, and a ticketed upper castle holding the Ahmediye Mosque, the Church of St. George, a citadel and a small history museum. Walk the ramparts for views over the Potskhovi river valley, then step inside the mosque and church — remarkably, each was pressed into service as the other''s faith at different points in its history. The museum covers the region''s layered Georgian-Ottoman-Russian past in a compact, air-conditioned space, a useful break from the heat or a wet-weather fallback. It''s the most polished single stop in the region and a natural first or last call on any Akhaltsikhe day.', 'Lower town (shops, vineyard, cafes) is free and open around the clock; the upper castle is ticketed roughly 10am-7pm daily, and the history museum inside closes earlier, around 6pm. Foreign-visitor tickets run ₾20 adult / ₾15 student or pupil, with children under 6 free; Georgian citizens and residents pay less. Both cash and card are accepted.', 'Morning for the paid castle, before tour groups and afternoon heat; evening for a free wander of the lower town', 150, '2.5 hr', 15, 20, '₾15-20', 'Akhaltsikhe', 41.6392, 42.9762, 'Ramparts and towers are great for kids to run and climb, but wear real shoes — the stone stairs are steep and uneven, and some upper wall sections have real drops with no barrier.', false, ARRAY['scenic', 'walk']::TEXT[], 1, NULL, NULL),
  ('samtskhe-javakheti-sapara', 'samtskhe-javakheti', 'Sapara Monastery', 'A 9th-century monastery hidden in pine forest, its 13th-century frescoes still watched over by resident monks.', 'Sapara Monastery climbs out of pine forest about 25 minutes southeast of Akhaltsikhe, founded in the 9th century and rebuilt by the Jakeli princes who ruled Samtskhe through the medieval period. The main church of St. Saba, from the 1200s, still holds 13th-century frescoes and is an active place of worship — monks live and work the grounds today, so the atmosphere stays quiet and unhurried compared with the region''s fortresses. A steep, unmarked forest path climbs from the monastery to an old defensive tower for a wider view over Akhaltsikhe and the valley, if you have the legs for it. There''s no cafe or shop on site, so it''s a stop for the setting and the silence rather than an amenity-filled visit.', 'Free entry, donations welcome. Modest dress required — women should carry a headscarf, and cover shoulders and knees. The paved access road is narrow and winding and turns slick when wet, so drive slowly after rain; there''s no shop or water for sale on site.', 'Morning, before the day heats up', 90, '1.5 hr', NULL, NULL, 'Free', 'Akhaltsikhe', 41.6114, 43.0906, 'The forest setting and optional climb to the old tower give kids somewhere to burn energy, but the tower path has no railings and real drops — this is a hold-hands hike, not a let-them-run-ahead one.', false, ARRAY['scenic', 'hike']::TEXT[], 2, NULL, NULL),
  ('samtskhe-javakheti-khertvisi', 'samtskhe-javakheti', 'Khertvisi Fortress', 'One of Georgia''s oldest fortresses, its walls rising above the cliff where the Mtkvari and Paravani rivers meet.', 'Khertvisi Fortress stands on a rocky spur above the point where the Paravani river meets the Mtkvari, with a core dating to the 10th century built over even older fortifications — plausibly among the oldest standing structures in Georgia. It''s a short, free stop on the drive to Vardzia: a five-sided watchtower, a square keep, the small 10th-century Church of St. George, and the collapsed remains of a tunnel that once ran down to the river for water during a siege. There''s little shade and no facilities, so it''s best treated as a leg-stretch and photo stop rather than a destination in its own right, but the setting — cliffs, two rivers, and the road winding on toward Vardzia — makes it worth the pause.', 'Free, roughly 9am-6pm (earlier at dusk in winter). No shade and no food or water on site — bring both if visiting midday in summer. The path up from the parking area is uneven dirt and gravel, and the fortress walls have unguarded drops in places.', 'Late afternoon light, or as a stop en route to Vardzia', 40, '40 min', NULL, NULL, 'Free', 'Khertvisi (Aspindza municipality)', 41.4028, 43.2942, 'Genuinely fun to explore, but the walls and old tunnel opening have real, unguarded drops — this is a hold-hands stop, not a free-range one.', false, ARRAY['scenic', 'walk']::TEXT[], 3, NULL, NULL),
  ('samtskhe-javakheti-vardzia', 'samtskhe-javakheti', 'Vardzia Cave City', 'A 12th-century cave city carved hundreds of chambers deep into a cliff, tunnels, stairs and all.', 'Vardzia is a 12th-century cave city that Queen Tamar''s engineers cut nearly 20 levels into a cliff above the Mtkvari, once holding thousands of interconnected chambers — churches, wine cellars, stables and living quarters — of which several hundred are still open to walk through. The centerpiece is the Church of the Assumption, its 12th-century frescoes including a portrait of Queen Tamar herself, reached via a warren of tunnels and stairs cut straight into the rock. A small community of monks and nuns still lives and works at Vardzia and at the neighboring convent of Zeda Vardzia, so parts of the complex remain a working religious site rather than a pure museum. Budget real time here — this is the region''s biggest single attraction and genuinely takes hours to see properly, not a quick stop.', '₾15 per person; audio guide +₾15; an optional shuttle from the car park to the site entrance runs ₾2 per person (it''s also an easy walk without it). Open daily, hours shift seasonally from roughly 10am-5pm in winter to 10am-7pm in summer. A rockfall near the ''Secret Tunnel'' in May 2026 damaged part of the exit route and its safety barrier — as of this writing, visitors backtrack through the complex rather than exiting via the usual one-way tunnel, which adds time; confirm current access with Akhaltsikhe tourist information before you drive out. Cash is the safer bet at the ticket office.', '10am opening, or May/September to avoid both midsummer heat and the biggest tour groups', 150, '2.5 hr', 15, 15, '₾15', 'Vardzia (Aspindza municipality)', 41.2044, 43.2874, 'Be honest with yourself about this one — there are many steep stairs, low tunnels you have to duck through, and stretches along an exposed cliff edge without barriers in places. Hold hands throughout; it is not stroller- or wheelchair-accessible, and isn''t the place for a child who bolts.', false, ARRAY['cave', 'hike', 'scenic']::TEXT[], 4, NULL, NULL),
  ('samtskhe-javakheti-abastumani-observatory', 'samtskhe-javakheti', 'Abastumani Astrophysical Observatory', 'A working astrophysical observatory in the mountains above a Romanov-era spa town, open for day and night tours.', 'The Abastumani Astrophysical Observatory sits on Mount Kanobili above the old Romanov-era spa town, a genuinely active research facility — around 120 staff still work here — rather than a preserved relic, and in 2024 it installed a new Austrian-built telescope, its most advanced instrument yet. Day tours walk you through the dome and telescope and let you talk with working astronomers about current research and the observatory''s Soviet-era history. In summer, the observatory also runs after-dark stargazing sessions through its telescopes, weather permitting — a genuine novelty for kids used to city light pollution. The historic cable car that once ferried staff up the mountain still runs but is reserved for observatory personnel, not visitors, so day-tour access is by road.', 'Day tours run May-August, roughly 11am-7pm, at ₾20 per person with a ₾100 minimum per booking — a small family group may need to confirm whether they''ll be joined with others to meet the minimum, or budget for it outright. Night stargazing sessions run 9pm-1am in summer at ₾40 per person (₾200 minimum) — a late night for younger kids, so weigh that against an early departure the next day. Book ahead rather than turning up; confirm current pricing and availability, as minimums and hours are set by the observatory and can shift season to season.', 'Clear summer evenings for stargazing; late morning for the day tour', 90, '1.5 hr', 20, 40, '₾20-40', 'Abastumani', 41.7542, 42.8264, 'The day tour suits any age; the night session is a real treat but runs until 1am, which is a late, cold, high-altitude night out for younger kids — dress warmly regardless of season.', true, ARRAY['scenic', 'evening']::TEXT[], 5, NULL, NULL),
  ('samtskhe-javakheti-abastumani-baths', 'samtskhe-javakheti', 'Abastumani Sulfur Baths', 'Warm sulfur pools in a restored 19th-century resort town — the region''s easiest rainy-day plan.', 'Abastumani''s sulfur baths draw on the same warm mineral springs that made this a fashionable Romanov-era spa retreat, with indoor thermal pools running 39-48.5°C year-round regardless of what the weather''s doing outside. It''s a straightforward, low-key soak rather than a spectacle — no grand bathhouse architecture to see, just a working therapeutic facility — but it''s genuinely relaxing after a day of fortress stairs and cave tunnels, and it''s the region''s most reliable indoor, weatherproof option. Sessions are billed by the hour, so it''s easy to keep a visit short if kids get restless in the water.', '₾20 per person per hour; open 8am-midnight daily. Sulfur water has a distinct smell that lingers on skin and swimwear — bring a spare set of clothes and don''t wear anything you''re precious about.', 'Any time — it''s an all-weather, all-season stop', 60, '1 hr', 20, 20, '₾20 per person per hour', 'Abastumani', 41.7462, 42.8501, 'Warm water and a low-key setting make this an easy win with tired kids, though the sulfur smell takes some getting used to.', false, ARRAY['water']::TEXT[], 6, NULL, NULL),
  ('samtskhe-javakheti-sakalmakhe', 'samtskhe-javakheti', 'Sakalmakhe Trout Restaurant', 'Trout pulled straight from a riverside holding pond and grilled under shaded pavilions on the Baratkhevi.', 'Sakalmakhe sits about ten minutes north of central Abastumani on the Baratkhevi River, built around shaded pavilions and tables set beside a small holding pond where the trout are kept alive until they''re ordered. Grilled trout is the reason to come — simple, fresh, and about as far from a tourist-menu refuel as this region gets — alongside mtsvadi (grilled meat skewers) if the table wants variety. The riverside setting, with the water running past the pavilions, makes it a genuine destination stop rather than somewhere you duck into between sights. It pairs naturally with an Abastumani day, either as a late lunch after the sulfur baths or dinner after the observatory tour.', 'Exact pricing wasn''t confirmed at time of writing — budget for a mid-range sit-down meal and confirm current prices on arrival. Seating is outdoor pavilions with limited cover, so check ahead in poor weather.', 'Lunch, to make the most of the riverside setting in daylight', 90, '1.5 hr', 25, 45, '₾25-45', 'Abastumani', 41.759, 42.854, 'Kids can watch the trout in the holding pond before they''re on the plate — a good pre-meal distraction, and the pavilions give shade to fidget under.', false, ARRAY['wine', 'water']::TEXT[], 7, NULL, NULL),
  ('samtskhe-javakheti-paravani-lake', 'samtskhe-javakheti', 'Lake Paravani', 'Georgia''s largest lake, a wind-scoured mirror on the high volcanic plateau near the Armenian border.', 'Lake Paravani is Georgia''s largest lake, a shallow, wind-rippled sheet of water spread across the Javakheti volcanic plateau at over 2,000m elevation, ringed by bare, treeless hills and used mainly by migratory birds and local fishermen. There''s no single formal viewpoint or visitor center — you pull off along the tarmac road that runs its eastern shore between Tsalka and Ninotsminda and walk down to the water, where the scale and stark, almost lunar landscape are the whole point. It''s a good stretch-the-legs stop for birdwatchers, and the lake freezes over in winter, drawing local ice skaters, though that''s not a family-trip season here. Bring more layers than the season back in Tbilisi would suggest — wind off the plateau is constant and can be biting even in summer.', 'No entrance fee, no facilities on site — bring water, snacks, and warm layers regardless of season. Best combined with Poka Convent, a few minutes further along the same shore road.', 'Clear, calm mornings — wind tends to pick up by afternoon', 60, '1 hr', NULL, NULL, 'Free', 'Ninotsminda', 41.47, 43.75, 'Flat, open ground is easy for kids to run on, but there''s no shade and the wind can be surprisingly strong — pack a windbreaker even in summer.', false, ARRAY['scenic', 'water']::TEXT[], 8, NULL, NULL),
  ('samtskhe-javakheti-poka-convent', 'samtskhe-javakheti', 'Poka Convent', 'A working convent on the lake shore where nuns make prize-winning cheese and cloisonne enamel icons.', 'Poka Convent sits on Lake Paravani''s shore in a village of the same name, home to a community of nuns known well beyond the region for the cheese, honey and bio sweets they make and sell from an on-site shop. Alongside the small working church, there''s a cloisonne enamel workshop producing icons and decorative pieces by hand — worth a look even if you don''t buy. It''s a low-key, unhurried stop that pairs naturally with the lake itself, and one of the more distinctive places to eat something in the whole region, given how far it is from anywhere else selling food.', 'No fixed entrance fee; the shop takes cash. Hours aren''t formally posted — this is a working convent, not a ticketed attraction, so a visit during reasonable daylight hours is safest.', NULL, 45, '45 min', NULL, NULL, 'Free', 'Poka (Ninotsminda municipality)', 41.4894, 43.7439, 'The cheese and sweets shop is an easy win with kids after a long, quiet drive across the plateau.', false, ARRAY['walk']::TEXT[], 9, NULL, NULL),
  ('samtskhe-javakheti-doukhobor-museum', 'samtskhe-javakheti', 'Doukhobor Museum, Gorelovka', 'A blue wooden house near Ninotsminda preserving the exiled Russian Doukhobor community''s history.', 'The Doukhobor Museum in Gorelovka, about 11 km southeast of Ninotsminda, is a small community-run house museum preserving the history of the Doukhobors — a pacifist Russian Christian sect exiled here by Tsarist authorities in the 1840s, distinguished by their blue-painted wooden houses and grass roofs. Inside is a former meeting hall with separate entrances once used by men and women, along with traditional embroidery and sewing made by local girls. Most of the original Doukhobor community emigrated to Canada in the 20th century, and only a small population remains, making this one of the few places to see their material culture still in Georgia. It''s a quiet, unusual stop that gives older kids a genuine, tangible history lesson rather than another church or fortress.', 'No formal ticket price — a small cash donation (a couple of GEL) is customary and appreciated. No fixed opening hours; it''s a community space rather than a staffed museum, so a visit isn''t guaranteed if no one''s there to open up — ask locally in Ninotsminda if unsure.', NULL, 45, '45 min', NULL, NULL, 'Free', 'Ninotsminda', 41.213, 43.689, 'Better suited to older kids (10+) who can engage with the history — younger kids may find a small house museum with no interactive elements a quick in-and-out.', false, ARRAY['walk']::TEXT[], 10, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Shida Kartli — 10 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Gori & the Uplistsikhe rock town',
  summary       = 'Shida Kartli is Georgia''s hot, flat inland heartland — wheat fields and vineyards ringing Gori, the birthplace of Stalin, with Uplistsikhe''s rock-cut cliff city a short drive east and a scatter of quiet frescoed monasteries most visitors drive straight past. It works well as a long day trip from Tbilisi or a one-night stop on the way west to Kutaisi. The region''s northern edge touches the unmarked administrative boundary line (ABL) with Russian-occupied South Ossetia, roughly 20km beyond Gori — every place in this catalog sits well south of it, but it''s worth knowing it''s there and not to head north off the main highway toward Tskhinvali.',
  when_to_go    = 'Best in spring (April-May) and autumn (September-October) — this is a hot, dry inland basin, and Uplistsikhe, Gori Fortress, and Ateni Sioni all sit fully exposed with essentially no shade. In July-August, do the outdoor sites before 10am or after 5pm and carry more water than feels necessary; midday heat here is sharper than in Tbilisi or the mountains. Winter is cold but quiet, with a discounted Uplistsikhe ticket and near-empty monasteries, though Rkoni''s dirt access road gets rough after rain or snow.',
  getting_there = 'Gori is about 85km (1-1.5hr) from Tbilisi on the S1 highway, good tarmac the whole way and the main road toward Kutaisi and the west, so most itineraries pass through anyway. Uplistsikhe is a further 15-20 minutes east of Gori on paved roads. Frequent marshrutkas run from Tbilisi''s Didube station to Gori (roughly 1.5hr, a few GEL); getting on to Uplistsikhe, Ateni, Kintsvisi, or Rkoni by public transport is thin to nonexistent, so a car, taxi, or a day tour based out of Gori is the practical option for the outlying sites.',
  base_towns    = 'Gori is the obvious base — central for Uplistsikhe, the Ateni valley, and the Stalin-era sites, with a handful of budget hotels and guesthouses. Most visitors coming from Tbilisi treat the region as one long day trip or a single-night stopover on the drive toward Kutaisi rather than a multi-night stay.'
WHERE id = 'shida-kartli';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('shida-kartli-gori-fortress', 'shida-kartli', 'Gori Fortress', 'A free hilltop citadel above Gori with sweeping views over the town and the Mtkvari valley.', 'Gori''s fortress sits on the volcanic-looking hill directly above the town center, rebuilt repeatedly from an early-medieval core through the 17th-19th centuries as control of the town changed hands. Steps lead up from the streets below to a compact circuit of stone walls and towers — there''s no ticket booth, gate, or fixed exhibit, just open access to climb and look around. From the top you get a full panorama over Gori''s grid, the Mtkvari river, and the plain running out toward Uplistsikhe and the hills beyond. It''s a five-minute climb rather than a hike, which makes it an easy add-on before or after the Stalin Museum a few blocks away.', 'No ticket booth or fixed hours — it''s an open, unstaffed site accessible any time there''s daylight. Stone stairs and wall-top sections are uneven and often unguarded, so watch your footing and supervise kids closely. No shade anywhere at the top; go early or late in summer. The hills visible to the north are well short of the South Ossetia boundary line (roughly 20km further on) — nothing about the view itself is close to it.', 'Early morning or golden hour', 30, '30 min', NULL, NULL, 'Free', 'Gori', 41.9861, 44.10806, 'Kids enjoy scrambling along the walls, but there are unguarded drops in places — hold hands near the edges rather than letting them range freely.', false, ARRAY['scenic', 'walk', 'kids']::TEXT[], 1, NULL, NULL),
  ('shida-kartli-stalin-museum', 'shida-kartli', 'Stalin Museum, Gori', 'The still-operating state museum dedicated to Gori''s most famous native son.', 'Gori''s state museum occupies a grand building constructed specifically to house it, and a guided visit moves through exhibition halls of personal photographs, gifts sent by world leaders, and personal effects, then out to a modest childhood home preserved under a marble pavilion, and finally to Stalin''s armored green private railway carriage parked behind the building. The museum is still state-run and presents its subject largely through his own biography and personal artifacts rather than a critical, contextualized account of the purges and famine — visitors going in expecting the latter should know this isn''t primarily that kind of museum. What''s actually here is real and well preserved: the halls, the birth house, and the carriage.', 'Open daily except Monday, roughly 10:00-18:00 (10:00-17:00 in winter) — some sources note Monday closures can shift in the low season, so check locally if visiting outside summer. Full ticket with guide, birth house, and carriage runs about ₾15; skip the carriage for ₾10, or see the carriage alone for ₾5.', 'Morning, before tour groups arrive', 90, '1.5 hr', 5, 15, '₾5-15', 'Gori', 41.987222, 44.113611, 'The armored green railway carriage is the highlight for most kids; the exhibition halls move at a slow, guided pace, so temper expectations for younger children.', false, ARRAY['cool', 'kids']::TEXT[], 2, NULL, NULL),
  ('shida-kartli-gori-museum', 'shida-kartli', 'Sergi Makalatia Gori Historical & Ethnographic Museum', 'A quiet indoor museum on Gori''s deeper history, including a sobering room on the 2008 war.', 'A low-traffic counterpart to the Stalin Museum a few streets away, this local history museum covers Gori and the wider Shida Kartli region through archaeological finds, traditional Georgian costumes and textiles, jewelry, and household furniture. A small dedicated room holds photographs and artifacts from the August 2008 Russia-Georgia war, when Gori itself was shelled and briefly occupied — a sober, factual counterpoint to the rest of the collection. It''s compact enough to see properly in under an hour and rarely has more than a handful of other visitors, which makes it a genuine change of pace from the crowds at the Stalin Museum.', 'Open 10:00-18:00 Tuesday through Saturday; closed both Sunday and Monday, which is unusual for the region — plan around it. Address is 12 Kirion II Street, a few blocks from the Stalin Museum; the exact building isn''t well mapped, so ask locally or at the tourist information office if you can''t find it. Students and schoolchildren pay less than the ₾3 adult rate.', NULL, 40, '40 min', 3, 3, '₾3', 'Gori', 41.9835, 44.1108, 'The 2008 war room includes photographs of shelling damage that may not suit the youngest visitors — worth a quick preview if traveling with small kids.', false, ARRAY['cool', 'walk']::TEXT[], 3, NULL, NULL),
  ('shida-kartli-chinebuli', 'shida-kartli', 'Chinebuli', 'The unpretentious local favorite across from the Stalin Museum, serving Gori''s best-value khinkali.', 'Chinebuli sits directly across the street from the Stalin Museum but pulls as many Gori locals as tourists, which says something about a menu built on solid, inexpensive Georgian standards rather than a captive-audience markup. Order khinkali by the piece, kharcho soup, or an Adjaruli or Mingrelian khachapuri, and expect generous portions for the price. It''s a straightforward, no-frills room rather than a scenic destination in itself, but it''s the kind of reliably good, honestly priced place regulars keep returning to rather than a tourist-trap refuel stop.', 'No reservations needed outside large groups; cash is the safer bet. Diners commonly report paying roughly ₾20-30 per person for a full meal — treat this as an estimate from reviewer reports rather than a fixed, published menu price.', 'Lunchtime', 60, '1 hr', 20, 30, '₾20-30', 'Gori', 41.987739, 44.114142, 'Big, shareable Georgian classics and a casual, noisy room — no need to worry about restaurant manners here.', false, ARRAY['wine', 'kids']::TEXT[], 4, NULL, NULL),
  ('shida-kartli-uplistsikhe', 'shida-kartli', 'Uplistsikhe Cave Town', 'A cliffside city carved entirely from rock, inhabited from the Bronze Age to the Middle Ages.', 'Uplistsikhe is a city carved directly into a rocky hillside above the Mtkvari river, not a single structure — walking it means climbing through hundreds of rock-cut chambers, tunnels, wine cellars, grain pits, and a pagan altar hall, up to a 9th-10th century Christian basilica built into the rock at the summit. A marked path loops through the site, but it''s uneven, steep in places, and involves real scrambling over worn stone. The scale and age of the place — occupied from roughly the early Iron Age through the 13th-14th centuries — is the payoff; a small site museum near the entrance gives context before the climb. Give this considerably longer than it looks from the entrance; most visitors underestimate it.', 'Open daily except Monday, roughly 10:00-17:00 (later in peak summer) — confirm hours if visiting off-season. Entry is ₾15, sometimes discounted to around ₾7 in winter low season. There is no shade anywhere on the hillside — bring a hat, sunscreen, and more water than feels necessary, and wear real shoes; sandals are a bad idea on the worn rock.', 'Early morning, to beat both heat and tour buses', 120, '2 hr', 7, 15, '₾7-15', 'Gori', 41.96553, 44.17119, 'Kids generally love clambering through the tunnels and pits, but the whole site is exposed rock with unguarded drops in places — keep a close hand on younger kids, especially in the heat.', false, ARRAY['cave', 'walk', 'scenic', 'kids']::TEXT[], 5, NULL, NULL),
  ('shida-kartli-ateni-sioni', 'shida-kartli', 'Ateni Sioni Church', 'A 7th-century domed church modeled on Jvari, with rare 11th-century frescoes still on its walls.', 'Modeled closely on Jvari Monastery near Mtskheta but built slightly later in the early 7th century, Ateni Sioni is a domed cross-in-square church standing alone above the Tana river in a quiet wine-growing valley about 10km south of Gori. Inside, the 11th-century frescoes are among the finest surviving medieval religious paintings in Georgia, depicting biblical scenes alongside portraits of Georgian nobility of the period. It sees a fraction of the visitors Jvari does despite the architectural similarity, and the valley setting — vineyard terraces climbing the slopes around it — is a big part of the appeal. It''s an active church, so expect it to be quiet rather than staffed.', 'No fixed visiting hours were found for this site — it''s generally accessible through the day, but if it''s locked, ask in the village for the caretaker. Free entry; donations welcomed. Modest dress (shoulders and knees covered) expected as at any working church.', 'Morning', 30, '30 min', NULL, NULL, 'Free', 'Ateni', 41.9039, 44.096, NULL, false, ARRAY['scenic', 'walk']::TEXT[], 6, NULL, NULL),
  ('shida-kartli-vacheishvili', 'shida-kartli', 'Vacheishvili Wine Cellar (Atenuri)', 'A family winery in the Ateni valley making Atenuri, once called "the wine of kings."', 'This small family winery in Ateni village makes Atenuri, a lightly sparkling white wine unique to this valley and made only from the local Chinuri and Goruli Mtsvane grapes — praised in old Georgian writing as fit for royalty. Walk the terraced vineyard and peek into the family cellar, a ten-minute stroll from Ateni Sioni church, and pick up a bottle to take home. It''s a genuinely small, family-run operation rather than a polished tourist winery, which is part of the appeal for anyone wanting a quieter alternative to the larger estates closer to Tbilisi.', 'Walking the grounds and cellar is free and informal, with no fixed tasting-room schedule. A sit-down tasting or meal needs to be arranged with the family in advance (via atenuri.ge) — the price for that experience isn''t published anywhere, so confirm it directly when you book. Bottled wine (e.g. Tavkveri or Chinuri) runs around ₾40 if you want to buy some to take home.', NULL, 45, '45 min', NULL, NULL, 'Free', 'Ateni', 41.913056, 44.093056, NULL, false, ARRAY['wine', 'scenic']::TEXT[], 7, NULL, NULL),
  ('shida-kartli-kintsvisi', 'shida-kartli', 'Kintsvisi Monastery', 'A forested 13th-century monastery hiding one of Georgia''s finest medieval fresco cycles.', 'Set on a wooded slope in the Dzama gorge about 25km from Gori, Kintsvisi is a monastic complex of three churches — the Church of the Virgin Mary, St. George, and St. Nicholas — plus a bell tower, shaded by surrounding trees rather than sitting exposed like most Shida Kartli sites. The Church of the Virgin Mary holds one of Georgia''s most celebrated fresco cycles, including a Hodegetria Virgin and a Communion of the Apostles scene rated among the finest surviving examples of medieval Georgian monumental painting. It''s a working, lightly visited monastery — expect to have the frescoes largely to yourself on a weekday.', 'The final stretch of road is unpaved but manageable in a normal car at a slow pace. Free entry, donations welcome; modest dress expected as at any active monastery. No food, water, or facilities on site.', 'Morning', 45, '45 min', NULL, NULL, 'Free', 'Kareli', 41.960533, 43.834309, NULL, false, ARRAY['scenic', 'walk', 'cool']::TEXT[], 8, NULL, NULL),
  ('shida-kartli-rkoni', 'shida-kartli', 'Rkoni Monastery & Queen Tamar Bridge', 'A ruined monastery reachable only by crossing a medieval queen''s bridge over the Tedzami River.', 'Rkoni is a ruined 7th-13th century monastery-and-fortress complex perched above the Tedzami river, reachable only by crossing a stone bridge locally attributed to Queen Tamar. From the bridge, a marked trail climbs the hillside past the monastery buildings to a small rock-hewn cave once used by resident monks, with views back down the narrow gorge. It''s one of the least-visited sites in this catalog — the access road past Garikula village is a rough dirt track that keeps the crowds away — and the surrounding valley is reportedly at its best in autumn foliage.', 'The last stretch from Garikula is an unpaved dirt road, slow going but passable in a normal car in dry weather; avoid it after heavy rain. No shops, water, or facilities anywhere near the site — bring everything you need. Phone signal is patchy for much of the approach, so download offline maps beforehand.', 'Autumn, for the foliage', 90, '1.5 hr', NULL, NULL, 'Free', 'Kaspi', 41.8075, 44.22472, 'The bridge crossing and cave scramble make this feel like a real adventure for kids, but there are no railings anywhere — hold hands on the bridge and near the cave opening.', false, ARRAY['hike', 'scenic']::TEXT[], 9, NULL, NULL),
  ('shida-kartli-surami', 'shida-kartli', 'Surami Fortress', 'A ruined hilltop fortress guarding the only road between eastern and western Georgia.', 'Surami''s ruined fortress sits on a hill above the small town, guarding the Surami (Rikoti) Pass — historically the only route connecting eastern and western Georgia, which is why whoever controlled this hill controlled the country''s main artery. What survives today is genuine ruins rather than a restored monument: a citadel, a palace footprint, and the small St. George church, rebuilt repeatedly between the 11th and 18th centuries. The fortress is the setting for "The Legend of Suram Fortress," a well-known Georgian folk tale and 1984 Sergei Parajanov film about a young man walled alive into the ramparts to keep them from collapsing. It''s a convenient stretch-your-legs stop on the long drive between Gori and Kutaisi or Borjomi, not a destination in its own right.', 'Free, unstaffed, and open access at any time — the ruins have uneven footing, so wear real shoes. Surami town, right below the fortress, is well known for roadside churchkhela stalls — a good stop to combine with the climb.', NULL, 30, '30 min', NULL, NULL, 'Free', 'Surami', 42.025, 43.5639, 'Climbing around the ruined walls is the main appeal for kids — supervise near crumbled edges since there''s no fencing.', false, ARRAY['scenic', 'walk', 'kids']::TEXT[], 10, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Svaneti — 12 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'Medieval towers under big mountains',
  summary       = 'Georgia''s most dramatic highland region: stone defensive towers rising straight out of villages under 5,000m peaks, reachable only by a long flight or road journey that is itself part of the trip. Mestia is the region''s hub — a walkable old quarter, an enterable Svan tower-house, and a proper museum for the days weather closes everything else down. Ushguli, one of Europe''s highest continuously inhabited settlements, anchors a full day trip along a road that has only recently become drivable without a dedicated 4x4. Add a glacier hike, a ropeway panorama, and a valley walk to the foot of Shkhara and there''s real variety packed into what is otherwise a genuinely remote corner of the country.',
  when_to_go    = 'Late June through September is the only fully reliable window — this is by far the most weather- and season-restricted region in this catalog. Outside those months the Mestia-Ushguli road, the high hiking trails, and the Zuruldi ropeway are frequently snowbound, closed, or simply not worth the risk, and several Svan villages are effectively cut off in winter. Even in season, plan morning starts: cloud and storms tend to build over the peaks by early afternoon, and both the ropeway and the Ushguli day trip depend on visibility and road conditions holding.',
  getting_there = 'Svaneti is the most remote region in this catalog, and getting there is its own undertaking. By road from Tbilisi: Tbilisi to Zugdidi is 5-6 hours by car or marshrutka, then Zugdidi to Mestia is a further roughly 3 hours on a since-rebuilt, mostly paved road through the Jvari Pass tunnels — call it 8-9 hours door to door. A direct daily marshrutka also runs from Tbilisi''s Navtlugi station at 07:00 (about 9-10 hours, roughly ₾50); the old overnight Tbilisi-Zugdidi train has been discontinued, so the full journey is now done by road. The alternative is flying: Vanilla Sky operates small 17-seat Twin Otter aircraft from Natakhtari, near Tbilisi, to Mestia in about 40 minutes, but these are visual-flight-rule flights that are frequently canceled for weather and only bookable within 30 days of departure — treat it as a bonus, not a plan to build a trip around. From Mestia, Ushguli is a separate rough-road leg: roughly 45 km that has been substantially rebuilt with asphalt and concrete in recent years, but the final few kilometers before Ushguli were still unfinished gravel as of the last check, and conditions can turn a 2.5-3 hour drive into much longer after rain or snow. A 4x4 or high-clearance vehicle is still the safe choice, especially outside peak summer.',
  base_towns    = 'Mestia is the only realistic base — it has the guesthouses, restaurants, and the ropeway and museum infrastructure, and every place in this catalog outside Ushguli is a manageable day trip from here. Most visitors day-trip Ushguli from Mestia rather than overnighting, though a single night in an Ushguli guesthouse lets you see the towers in empty early-morning light before the day''s 4x4 convoys arrive.'
WHERE id = 'svaneti';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('svaneti-mestia-old-town', 'svaneti', 'Mestia Old Town & Svan Towers', 'Cobbled lanes and stone defensive towers rising straight out of a working mountain town.', 'Wander the compact center around Seti Square, where 19th- and 20th-century wooden guesthouses sit beside centuries-old Svan defensive towers, all backed by the peaks ringing the valley. Most towers are still attached to private homes, so this is a street-level wander rather than a checklist of interiors — the point is the overall texture of a living mountain town rather than any single monument. Gear shops, bakeries, and cafes line the square if you need last-minute hiking supplies before heading further out. It''s the natural first stop to get oriented before tackling the region''s longer day trips.', 'Free to wander. Most towers are private homes — admire from the street unless a sign or guesthouse explicitly invites you in.', 'Late afternoon or early evening, once the day''s 4x4 convoys have returned', 60, '1 hr', NULL, NULL, 'Free', 'Mestia', 43.0459, 42.7281, 'Flat, easy walking with towers to spot and count — good for a low-key first evening after a long travel day.', false, ARRAY['scenic', 'walk']::TEXT[], 1, NULL, NULL),
  ('svaneti-cafe-laila', 'svaneti', 'Café Laila', 'One of Mestia''s oldest cafés, still turning out honest khinkali and khachapuri with occasional live singing.', 'Café Laila has been a fixture on Seti Square since long before Mestia was a tourist hub, and it''s kept its reputation for solid, unpretentious Georgian food — khinkali, khachapuri, kubdari (the local spiced-meat pie), and hearty soups. The room has a warm, funky, well-worn atmosphere, and reviews mention a Georgian choir performing some evenings, though this isn''t a fixed schedule. It draws a mix of guides, locals, and travelers rather than feeling purely tourist-oriented. It''s an easy walk from anywhere in the old town, making it a natural anchor for a Mestia evening.', 'Cash only. Kitchen service can slow considerably at peak dinner hours, with some visitors reporting close to an hour''s wait — order early or come slightly off-peak. Menu prices weren''t independently confirmed; budget roughly ₾25-45 per person and check the posted menu on arrival. The ₾25-45 a head is an estimate from reviews rather than a published menu — check prices when you order.', 'Dinner — live Georgian singing sometimes happens in the evening, though it''s not scheduled or guaranteed', 90, '1.5 hr', 25, 45, '₾25-45', 'Mestia', 43.0455, 42.7288, 'Big shareable Georgian plates and a relaxed, noisy room — fine for restless kids.', false, ARRAY['wine', 'evening']::TEXT[], 2, NULL, NULL),
  ('svaneti-margiani-house', 'svaneti', 'Margiani House-Museum', 'Climb inside a real medieval Svan defensive tower that most day-trippers walk straight past.', 'Tucked in the Lanchvali quarter above central Mestia, this preserved family residential complex pairs an 11th-century dwelling with a 10th-century defensive tower you can actually climb, floor by floor, up steep interior ladders to the roof. It''s one of the few Svan towers in the region set up for visitors to enter rather than just photograph from outside, and the family who maintains it can walk you through how these tower-houses functioned — livestock below, living quarters above, a fortified retreat on top. The climb itself, on narrow wooden ladders through low openings, is part of the experience. From the roof you get a genuine sense of why every old Svan family wanted one of these.', 'About a 10-minute uphill walk from the central square on a steep cobbled street — not stroller-friendly. Cash only; closed Mondays.', NULL, 60, '1 hr', 10, 10, '₾10', 'Mestia', 43.0425, 42.7268, 'The steep climb inside on narrow wooden ladders is exciting for older kids but tricky for toddlers.', false, ARRAY['scenic']::TEXT[], 3, NULL, NULL),
  ('svaneti-museum', 'svaneti', 'Svaneti History & Ethnography Museum', 'Icons, medieval armor, and a 1,700-year-old Svan weaving loom — the region''s best bad-weather fallback.', 'This branch of the Georgian National Museum on Ioseliani Street holds over 4,000 items pulled from Svaneti''s churches and villages: painted and engraved icons, weapons and armor, silverware, textiles, and an extraordinary ancient wooden loom. It''s a genuinely indoor, all-weather option in a region with very few of them, and gives useful context for the towers and churches you''ll see everywhere else. Displays are modest in scale but dense — expect to read rather than just glance. Guided tours are available if you want more depth than the labels provide.', 'Open 10:00-18:00 daily except Monday. Reported adult admission runs ₾7-10 depending on the source — confirm at the door; a guided tour costs roughly ₾10 extra.', 'Rainy days, or the hottest hour of a summer afternoon', 60, '1 hr', 7, 10, '₾7-10', 'Mestia', 43.0463, 42.7269, NULL, false, ARRAY['cool']::TEXT[], 4, NULL, NULL),
  ('svaneti-zuruldi-ropeway', 'svaneti', 'Zuruldi Ropeway (Hatsvali)', 'A two-stage cable car straight out of Mestia to a 2,347m ridge with a full Caucasus panorama.', 'This two-stage cable car climbs from a lower station on the edge of Mestia, over the Hatsvali ski slopes, to a cafe and viewpoint on the Zuruldi ridge at 2,347m, with Ushba and Tetnuldi visible across the valley on a clear day. It doubles as a ski lift for the Hatsvali resort in winter, but for most of the year it''s a scenery-only ride. The top station has a cafe if you want to linger over the view rather than just snap a photo and head back down. It''s the easiest big-mountain panorama in the region — no hiking required.', 'A return ticket covers both stages. Operating dates and hours vary by season and aren''t fully reliable — in 2026 it opened later than usual (August 8) — so confirm it''s running before building a day around it.', 'Clear mornings, before afternoon cloud builds over the peaks', 120, '2 hr', 25, 25, '₾25 return (both stages)', 'Mestia', 43.039217, 42.729943, 'An easy, exciting way for kids to get a real mountain view without a hike.', false, ARRAY['scenic', 'kids']::TEXT[], 5, NULL, NULL),
  ('svaneti-chalaadi-glacier', 'svaneti', 'Chalaadi Glacier Trail', 'A forest walk to a glacier tongue you can get close to, with no technical gear or experience needed.', 'A dirt road runs about 9-10 km from Mestia to a suspension bridge over the Mestiachala river; from there it''s roughly 3 km (40-60 minutes) each way on a shaded forest trail alongside the glacial meltwater to the Chalaadi glacier''s snout. It''s one of the most accessible glaciers in the Caucasus — a clear, well-trodden path with no ropes or scrambling — but it is a half-day outing once you add the drive to the trailhead. The glacier ice and surrounding moraine are worth the walk even for non-hikers, and the forest keeps most of the route shaded and cool.', 'Reach the trailhead by taxi, rental car, or on foot/bike from town (walking or cycling from Mestia adds roughly 2 hours each way). A taxi to the bridge runs roughly ₾30-40 each way. Wear real shoes — the ground near the ice is loose moraine rock.', 'Morning, for the clearest light and coolest walking temperature', 180, '3 hr', NULL, NULL, 'Free', 'Mestia', 43.117124, 42.696214, 'Manageable for kids around 7-8 and up in proper hiking shoes; too far and rocky for strollers or very young children.', false, ARRAY['hike', 'cool', 'scenic']::TEXT[], 6, NULL, NULL),
  ('svaneti-koruldi-lakes', 'svaneti', 'Koruldi Lakes', 'Alpine lakes at 2,700m below a jagged wall of peaks, reachable only by rough 4x4 track or a serious hike.', 'High above Mestia, the Koruldi Lakes sit at roughly 2,700m with an open panorama of the Svaneti peaks behind them. Most visitors reach them by hired 4x4 up a rough jeep track, followed by a short walk to the shore; committed hikers can also walk the whole way up from Mestia, which turns this into a genuinely long day. Either way, this is not a quick stop — the track alone takes real time and jolts hard in places, and weather at this altitude can close in fast. The reward is one of the best ridge-and-lake panoramas accessible without a multi-day trek.', 'Treat this as a half-day-to-full-day undertaking, not a quick stop, even with the 4x4 option. A shared 4x4 seat runs roughly ₾60 per person; a private vehicle round trip is more like ₾150-250, and prices are negotiable with drivers in Mestia. June-September only — the track is exposed and can close after storms.', 'June-September only; start early to be down before afternoon cloud and storms build at altitude', 300, '5 hr', 60, 250, '₾60-250', 'Mestia', 43.0877, 42.7033, 'The rough 4x4 track is long and jolting — better suited to older kids than toddlers or anyone prone to carsickness.', false, ARRAY['hike', 'scenic']::TEXT[], 7, NULL, NULL),
  ('svaneti-mazeri-ushba', 'svaneti', 'Mazeri & the Ushba Glacier Viewpoint', 'A quieter village with an up-close view of Ushba, the ''Matterhorn of the Caucasus,'' that most itineraries skip.', 'Mazeri is a small village about 15 km from Mestia in the Becho valley, sitting almost directly beneath the twin-peaked Ushba massif. From the village, a trail climbs through pine forest and alpine meadow along the Dolra river; after roughly 1-1.5 hours you reach a viewpoint over Georgia''s tallest waterfall (Shdugra) with Ushba and its glacier filling the skyline. The full route continues much further to the glacier itself, but that''s a strenuous 8-9 hour round trip for serious trekkers only — the viewpoint is where a day-tripper should turn back. It''s one of the best mountain views in the region and sees a fraction of Ushguli''s traffic.', 'Stop at the 1-1.5 hr (each way) viewpoint rather than pushing on to the glacier, which needs real trekking fitness and a full day. Taxi from Mestia runs roughly ₾160-200 return; a normal car can also make the drive.', 'June-September; clouds tend to roll in over Ushba by early afternoon', 270, '4.5 hr', NULL, NULL, 'Free', 'Mazeri', 43.074806, 42.610306, 'The walk to the viewpoint suits older, fit kids; the extension to the glacier itself is not a kids'' hike.', false, ARRAY['hike', 'scenic']::TEXT[], 8, NULL, NULL),
  ('svaneti-ushguli-chazhashi', 'svaneti', 'Ushguli & Chazhashi Tower Village', 'One of Europe''s highest inhabited settlements, its UNESCO-listed core still bristling with medieval towers.', 'Ushguli is a cluster of four hamlets at around 2,100m, and Chazhashi — its best-preserved hamlet and the part actually inscribed by UNESCO — is where the tower-and-house skyline is most dramatic. Wander the stone lanes between towers that have stood since the 9th-13th centuries, with Shkhara''s snowfields visible up the valley on a clear day. This is the region''s single unmissable stop, but it''s also a genuine commitment given the drive from Mestia, so most visitors pair it with Lamaria Church and the Ethnographic Museum on the same day. The setting under Shkhara is as much the draw as any individual building.', 'Most towers are private homes — don''t assume you can walk in; see the Ushguli Ethnographic Museum listing for an interior you can actually visit. Effectively a summer-only destination: the road is difficult or closed roughly outside June-October, and Ushguli itself can be snowbound in winter.', 'Morning, before the day''s 4x4 convoys from Mestia arrive', 90, '1.5 hr', NULL, NULL, 'Free', 'Ushguli', 42.915, 43.00861, 'Uneven cobbled lanes and open irrigation channels between the towers — keep an eye on younger kids.', false, ARRAY['scenic', 'walk']::TEXT[], 9, NULL, NULL),
  ('svaneti-lamaria', 'svaneti', 'Lamaria Church & Shkhara Viewpoint', 'A 9th-century hilltop church above Ushguli framed against Georgia''s highest peak.', 'On the northern edge of Zhibiani, one of Ushguli''s four hamlets, this small Georgian Orthodox church dates to roughly the 9th-10th century and is still an active place of worship. A short climb from the village brings you to the churchyard, from where Shkhara (5,193m, Georgia''s highest point) fills the skyline when the clouds cooperate. It''s a quick add-on to an Ushguli visit rather than a destination in its own right, but the view is one of the best in the region. Modest dress is expected, as at any working Georgian church.', 'Modest dress expected. Shkhara is frequently in cloud — a clear view is a matter of timing and luck, not something to count on.', 'Golden hour, for the best light on Shkhara when it''s visible', 45, '45 min', NULL, NULL, 'Free', 'Ushguli', 42.918354, 43.019656, NULL, false, ARRAY['scenic', 'walk']::TEXT[], 10, NULL, NULL),
  ('svaneti-shkhara-viewpoint', 'svaneti', 'Shkhara Glacier Valley Hike', 'A 16km round-trip valley walk, or horseback ride, to a close-up view of Georgia''s highest peak and its glacier.', 'From Ushguli, a trail follows the open floor of the Enguri valley past grazing horses and cattle toward the base of Shkhara, ending at a viewpoint with the glacier and Shkhara''s ice wall directly ahead. On foot it''s about 16 km round trip and a genuine 5-6 hour commitment; hiring a horse and local guide in Ushguli covers the same ground faster, in roughly 4-5 hours, and is the more popular option for anyone not up for a full day''s walk. Either way there''s no technical difficulty, just distance and exposure — flat valley walking with big views rather than climbing.', 'The walk starts in Ushguli and follows the Enguri valley east towards the glacier, so there is no single trailhead to aim for — head upstream from the village. On foot this is a real 5-6 hour round trip — bring water, sun protection, and sturdy shoes; there''s no shade in the valley. Horses can be hired in Ushguli, typically around ₾70 per horse plus a roughly ₾200 guide fee shared across the group — confirm current rates locally, as they aren''t fixed.', 'June-September only; start by 8am to be back before afternoon weather closes in', 330, '5.5 hr', NULL, NULL, 'Free', 'Ushguli', NULL, NULL, 'Too long and exposed for young kids on foot; older kids may manage it on a hired horse with a guide.', false, ARRAY['hike', 'scenic', 'thrill']::TEXT[], 11, NULL, NULL),
  ('svaneti-ushguli-museum', 'svaneti', 'Ushguli Ethnographic Museum', 'A 13th-century stone machubi packed with Svan looms, cradles, and centuries of household tools.', 'This small museum occupies a machubi, a traditional multi-story Svan stone house, with livestock quarters on the ground floor and family living space above — a hands-on look at how Ushguli households actually functioned for centuries. Highlights include a Svan cradle, an old hearth and bread oven, a stone cellar, and a loom said to be around 1,700 years old. It''s compact but a good complement to wandering Chazhashi''s exteriors, giving you an interior to actually step inside. It also works as Ushguli''s own fallback if the weather turns while you''re there.', 'Cash only. Hours are locally run and can be inconsistent — don''t count on a late-afternoon visit; ask at your guesthouse or in the village for the current opening pattern.', NULL, 30, '30 min', 10, 10, '₾10', 'Ushguli', 42.9145, 43.0095, NULL, false, ARRAY['cool']::TEXT[], 12, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

-- ==================================================================
-- Tbilisi — 12 places
-- ==================================================================

UPDATE catalog_regions SET
  subtitle      = 'City, views, sulfur baths',
  summary       = 'Georgia''s capital sprawls along a bend in the Mtkvari River, stacking Persian-tiled bathhouses, Soviet-era cable cars, and a UNESCO-adjacent old town under a hilltop fortress. It''s a genuinely walkable city for a family: the sights cluster into a few compact neighborhoods, most of the outdoor ones are free, and cable cars turn steep hillsides into a ride rather than a climb. Expect hot, dry middays in summer and beautiful, cooling evenings, with the sulfur baths and the national museum as your indoor refuge when the heat — or a rainy day — demands it.',
  when_to_go    = 'Best April-June and September-October for mild days. July-August is hot and dry at midday (often 32-35°C) but evenings cool off nicely, so front-load sightseeing to before 11am and after 5pm and save midday for the museum, a bathhouse, or a pool. Winter (Dec-Feb) is cold but every sight here stays open and crowds thin right out.',
  getting_there = 'Tbilisi International Airport (TBS) sits about 18 km southeast of downtown. Bolt or Yandex Go from the arrivals hall run roughly ₾20-30 and take 30-40 minutes depending on traffic — agree the fare or confirm the in-app price before getting in, since unmetered taxi touts at the airport routinely try to overcharge arriving tourists. Bus 337 runs from outside arrivals into the center roughly every 20-30 minutes (about 06:50-23:00) for ₾1 with a MetroMoney card, taking about 50 minutes — cheap but slow with luggage and kids. The airport-to-station rail link has not run since 2023, so don''t plan around it. Once in the city, buy a MetroMoney card (₾2 non-refundable deposit) at any metro station or kiosk: it covers the metro, city buses, and both cable cars, with the first ride costing ₾1 and any transfer within 90 minutes free. The metro is fast for crossing town but has only two lines and few elevators, so a folding stroller travels better than a pram. Bolt and Yandex Go are cheap and reliable for door-to-door hops (often under ₾1/km), especially in the heat or after dark, while the old town and Rustaveli Avenue are best covered on foot.',
  base_towns    = 'Base in or around the Old Town (Sololaki, Abanotubani) for walkability to the sights, or in Vera/Vake for a quieter, more residential feel with good restaurants and closer access to Turtle Lake and the Botanical Garden. Neither choice locks you out of anything here — nothing described below is more than a 15-20 minute Bolt ride from the other.'
WHERE id = 'tbilisi';

INSERT INTO catalog_places (
  id, region_id, name, hook, description, tips, best_time,
  duration_min, time_needed, price_gel_min, price_gel_max, price_lari,
  nearest_town, lat, lng, kid_note, booking_required, tags, sort_order,
  guide_script, guide_script_words
) VALUES
  ('tbilisi-old-town', 'tbilisi', 'Old Town Wander (Sioni & Abanotubani)', 'Cobbled lanes and carved wooden balconies that thread from Sioni Cathedral down into the bathhouse district.', 'Start at Sioni Cathedral and wander the pedestrianized lanes of Old Tbilisi, past ornate carved wooden balconies, small courtyards, and cafes selling churchkhela and Georgian wine. The streets funnel naturally down into Abanotubani, the brick-domed sulfur bath district, and up toward the Narikala cable car, so this isn''t a detour — it''s the connective tissue between the neighborhood''s other stops. Photogenic corners appear constantly and there''s no real route to get wrong. Evenings are best: the heat breaks, lanes fill with locals, and restaurant terraces open up.', 'Free to wander; the cobbles and occasional steps aren''t stroller-friendly in every lane, so a carrier works better for the youngest kids.', 'Early evening, once the midday heat breaks', 90, '1.5 hr', NULL, NULL, 'Free', 'Tbilisi', 41.691314, 44.807525, 'Flat-ish and easy to bail out of early if legs give out — there''s an ice cream or churchkhela stall every block.', false, ARRAY['walk', 'evening']::TEXT[], 1, NULL, NULL),
  ('tbilisi-narikala', 'tbilisi', 'Narikala Fortress & Cable Car', 'A 90-second cable car ride over the old town to a hilltop fortress with the best views in the city.', 'The cable car climbs from Rike Park to Narikala ridge in under two minutes, giving instant panoramic views over the old town''s tiled roofs, the Mtkvari River, and the giant Mother of Georgia statue standing guard above. From the upper station, walk the fortress walls and ramparts along the ridge — parts of the fortress interior have been under intermittent restoration in recent years, so treat the walk and viewpoints as the main event rather than any single building. It''s the single best orientation point for the city and works at any time of day, though sunset is the local favorite. Most visitors ride up and then walk back down through the old town rather than paying for the cable car twice.', 'Cable car is ₾2.5 one-way / ₾5 return, paid with a MetroMoney card; runs roughly 10am-midnight in summer, shorter hours in winter. Check locally on the day for which fortress sections are open, since restoration works have opened and closed different areas over the past couple of years. No shade on the ramparts, so bring hats and water in summer.', 'Late afternoon into sunset', 75, '1 hr 15 min', 3, 5, '₾2.5-5', 'Tbilisi', 41.68778, 44.80861, 'The cable car ride itself is the highlight for most kids; the ramparts have some unguarded drops, so keep a hand on younger ones.', false, ARRAY['scenic', 'kids']::TEXT[], 2, NULL, NULL),
  ('tbilisi-sulfur-baths', 'tbilisi', 'Abanotubani Sulfur Baths', 'Soak in naturally hot sulfur water inside brick-domed bathhouses that give the district its name.', 'Abanotubani''s brick domes sit over natural hot sulfur springs that have drawn bathers since the city''s founding legend. Book a private room at Chreli-Abano, Bath House No. 5, or one of the smaller family-run baths for an hour soaking in the hot mineral pool, usually with a cold plunge pool and sauna included in the better rooms. Add the traditional kisa scrub — a brisk, full-body exfoliation with a rough mitt — as a separate paid extra if the whole family is up for it; it''s intense rather than relaxing, and not for the ticklish. The smell is genuinely sulfurous and the water can stain light swimwear, so bring a dark suit and don''t expect subtlety.', 'Private rooms run roughly ₾15-200/hour depending on the bathhouse and room grade; smaller side-street baths are the cheapest but most basic. The kisa scrub is a separate ₾10-30 charge plus a small tip for the attendant. Most small bathhouses are cash-only; Chreli-Abano is one of the few with online booking. Not recommended during pregnancy or with open skin conditions.', NULL, 75, '1 hr 15 min', 15, 200, '₾15-200', 'Tbilisi', 41.687454, 44.810772, 'Fine for kids as a novelty soak, but the scrub is intense and the sulfur smell is strong — let younger kids opt out rather than push it.', false, ARRAY['cool']::TEXT[], 3, NULL, NULL),
  ('tbilisi-bridge-rike', 'tbilisi', 'Bridge of Peace & Rike Park', 'A glass-and-steel footbridge that lights up after dark, linking the old town to a riverside park.', 'Michele De Lucchi''s curved glass canopy crosses the Mtkvari River in a wave of steel ribs that light up with a slow-changing LED pattern after sunset, genuinely striking rather than a gimmick. It connects the old town directly to Rike Park on the far bank, a modern riverside green space with open lawns, a playground, and the lower cable car station up to Narikala. The whole loop — bridge, park, a lap along the riverbank — makes an easy, flat, free evening outing that tires kids out without taxing anyone''s patience.', 'Free and always open; best after dark for the bridge lighting. The deck can get crowded and slick underfoot after rain.', 'After sunset', 45, '45 min', NULL, NULL, 'Free', 'Tbilisi', 41.6929, 44.8082, 'Flat and stroller-friendly, with a playground in Rike Park to burn off pre-dinner energy.', false, ARRAY['evening', 'scenic', 'walk']::TEXT[], 4, NULL, NULL),
  ('tbilisi-mtatsminda', 'tbilisi', 'Mtatsminda Park & Funicular', 'A century-old funicular hauls you up Tbilisi''s tallest hill to an amusement park with the whole city laid out below.', 'The 1905 funicular climbs from Chonkadze Street to the top of Mtatsminda mountain in about five minutes, one of the steepest rides of its kind still running. At the top, Mtatsminda Park has a Ferris wheel, a rollercoaster, and a handful of smaller rides alongside cafes and the best sunset view over the city — the ponchiki (fried dough) stall near the top station is a local ritual, not just a tourist trap. Entry to the park itself is free; you pay per ride or per funicular trip on a rechargeable card. Give it a full evening rather than a quick stop — the lit-up city after dark is the actual payoff.', 'Funicular is roughly ₾10 per ride (up and down charged separately) plus a ₾2 reusable card fee; rides inside the park are priced individually on the same card. Go up an hour or so before sunset to get a table or bench with a view before the evening rush.', 'Sunset into early evening', 150, '2.5 hr', 10, 40, '₾10-40', 'Tbilisi', 41.6933, 44.7802, 'One of the best kid stops in the city — funicular plus fairground rides plus donuts; pace it so the youngest doesn''t melt down before sunset.', false, ARRAY['kids', 'evening', 'scenic']::TEXT[], 5, NULL, NULL),
  ('tbilisi-sameba', 'tbilisi', 'Holy Trinity Cathedral (Sameba)', 'A colossal gold-domed cathedral on its own hilltop, the third-tallest Orthodox cathedral in the world.', 'Consecrated in 2004, Sameba dominates the Tbilisi skyline from Elia Hill on the river''s east bank, its gold cross topping out at over 100 meters. The scale is the point — vast interior spaces, a sweeping terraced approach, and views back over the old town from its own grounds. It''s an active cathedral rather than a museum piece, so expect services, incense, and a genuinely devotional atmosphere alongside the tourists. The grounds around it are open and easy to wander even if you skip the interior.', 'Free entry; modest dress required — shoulders and knees covered, headscarves for women, wraps usually available at the door. It sits up a hill with limited shade, so it pairs well with a short Bolt ride rather than a walk in summer heat.', 'Morning, before the heat builds', 40, '40 min', NULL, NULL, 'Free', 'Tbilisi', 41.6975, 44.81667, 'The sheer size registers with kids even when the theology doesn''t — good for a quick, low-effort stop.', false, ARRAY['scenic']::TEXT[], 6, NULL, NULL),
  ('tbilisi-chronicles', 'tbilisi', 'Chronicles of Georgia', 'Sixteen soaring bronze pillars on a hilltop above the Tbilisi Sea, dramatic and largely missed by day-trippers.', 'Unofficially called the ''Georgian Stonehenge,'' this unfinished monument stacks 30-35 meter bronze pillars carved with scenes from Georgian history and Biblical stories, arranged on Keeni Hill overlooking the Tbilisi Sea reservoir. Construction stalled decades ago and the site is still rough around the edges — no ticket booth, no gift shop, just the scale of the columns and a genuinely wide view over the water. It sits far enough from the old town that few tour groups bother, which is exactly the appeal for families who''ve had enough queues elsewhere.', 'Free; no formal opening hours or staff on site, so it''s accessible dawn to dusk. There''s a set of steps up from the car park and no railings around some of the columns, so keep an eye on kids who like to climb. Best reached by taxi or Bolt (about 20-25 min from the old town) — there''s no useful public transit link.', 'Late afternoon, for the light on the pillars', 40, '40 min', NULL, NULL, 'Free', 'Tbilisi', 41.770503, 44.810438, 'The giant carved pillars and open hilltop are a hit, but there are no railings in places — hold hands near the edges.', false, ARRAY['scenic']::TEXT[], 7, NULL, NULL),
  ('tbilisi-museum', 'tbilisi', 'Georgian National Museum (Treasury)', 'Millennia-old gold jewelry in a cool, air-conditioned hall, the city''s best answer to a scorching or rainy day.', 'The Simon Janashia building on Rustaveli Avenue houses the Museum of Georgia''s headline exhibits, above all the Archaeological Treasury: pre-Christian gold and silver work, including the famous small golden lion, pulled from burial sites across the country. A separate Soviet Occupation exhibit covers 20th-century history in more sobering detail, better suited to older kids and adults. The building is fully air-conditioned, making it the single best indoor refuge in the city on a 35°C afternoon or a rain-soaked morning.', 'Closed Mondays. Tickets run roughly ₾20-35 for adults, discounted for children and students; the Treasury sometimes needs a separate small fee or timed-entry slot in peak season — check at the desk.', 'Midday, as a heat or rain refuge', 90, '1.5 hr', 20, 35, '₾20-35', 'Tbilisi', 41.696043, 44.800221, 'The gold Treasury room holds younger kids'' attention better than the general history halls do — lead with that.', false, ARRAY['cool']::TEXT[], 8, NULL, NULL),
  ('tbilisi-dry-bridge', 'tbilisi', 'Dry Bridge Market', 'A sprawling flea market of Soviet medals, old cameras, carpets, and junk, spread along the riverside embankment.', 'Vendors lay out blankets and folding tables along Dry Bridge (Sukhi Khidi) most days, selling everything from Soviet military medals and porcelain to vinyl records, carpets, and genuine antiques mixed in with reproductions. It''s as much a browse-and-people-watch stop as a shopping trip — haggling is expected and part of the fun, even if you don''t buy anything. Late afternoon into evening is liveliest, when it''s cooler and more vendors are out.', 'Cash only, and haggle — first prices are inflated for tourists. Authenticity varies wildly on ''antique'' items; treat anything without solid provenance as a curiosity, not an investment. Busiest and best-stocked on weekends.', 'Late afternoon', 45, '45 min', NULL, NULL, 'Free', 'Tbilisi', 41.70124, 44.803312, 'More interesting for older kids who can browse independently than for younger ones — it''s a lot of standing and looking, not touching.', false, ARRAY['evening', 'walk']::TEXT[], 9, NULL, NULL),
  ('tbilisi-botanical-garden', 'tbilisi', 'Tbilisi Botanical Garden & Waterfall', 'A shaded gorge garden behind Narikala fortress, with a 22-meter waterfall as the payoff at the end of the path.', 'Tucked into the Tsavkisi-Tskali gorge just behind the Narikala ridge, this 128-hectare garden is a genuinely cool, green escape from the old town''s stone and heat — winding paths through thousands of plant species lead back to a 22-meter waterfall cutting straight down the rock face. It''s shaded for most of the walk, gently sloped rather than steep, and quiet even in high season since most visitors skip it for the fortress next door. The waterfall''s flow varies by season, fullest in spring and thinner by late summer, but it rarely runs dry.', '₾4 adult entry, ₾6 for a family ticket; open 9am-7:30pm year-round. The path to the waterfall is unpaved in places, so trainers work better than sandals. Bring water — there are few kiosks inside.', 'Late morning, before the midday heat', 90, '1.5 hr', 4, 6, '₾4-6', 'Tbilisi', 41.68611, 44.8075, 'Shaded, easy walking, and a real waterfall at the end — one of the better cool-off, low-effort stops for younger kids.', false, ARRAY['cool', 'walk', 'kids']::TEXT[], 10, NULL, NULL),
  ('tbilisi-turtle-lake', 'tbilisi', 'Turtle Lake (Kus Tba)', 'A short cable car over Vake Park to a hillside lake with pedal boats, cafes, and a 1km path around the water.', 'A short cable car ride from Vake Park lifts you to Turtle Lake, a modest reservoir on the northern slope of the Mtatsminda ridge that doubles as Tbilisi''s easiest lakeside outing. Rent a pedal boat, walk the roughly 1km path around the shore, or just sit at one of the lakeside cafes — it''s unhurried and genuinely local rather than built for tourists. The Open-Air Museum of Ethnography, with relocated wooden houses from across Georgia, sits on the hill just above if there''s appetite for one more stop.', 'Cable car from Vake Park is around ₾1-2 one-way on a MetroMoney card; a taxi up is also cheap and quick if you''d rather skip the ride. Lakeside cafes are pricier than average — budget for it or bring your own snacks. Water rides and full cafe service scale back in winter.', 'Late afternoon', 90, '1.5 hr', 1, 2, '₾1-2 (cable car)', 'Tbilisi', 41.700391, 44.754455, 'Pedal boats and open grass to run on make this one of the more relaxed, low-stakes afternoons for younger kids.', false, ARRAY['kids', 'water', 'walk']::TEXT[], 11, NULL, NULL),
  ('tbilisi-keto-kote', 'tbilisi', 'Keto da Kote', 'A Vera townhouse restaurant doing Georgian classics well enough to be a destination meal, not just a refuel.', 'Set in a restored townhouse in the Vera neighborhood, Keto da Kote serves the Georgian staples — khinkali, khachapuri, badrijani (walnut-stuffed eggplant rolls), mtsvadi — cooked with more care and better ingredients than the average tourist-strip version, and it''s earned a spot on regional ''best of'' lists for it. The terrace seating is the draw in warm weather; the menu is long enough that a big table can order family-style and cover most of the greatest hits in one sitting. It''s a proper sit-down meal rather than a quick bite, so plan it as an evening anchor rather than a stop between sights.', 'Reserve 3-7 days ahead for a weekend table, especially for the terrace. Budget roughly ₾45-80 per person with wine. Busiest after 8pm.', 'Dinner, after 7pm', 90, '1.5 hr', 45, 80, '₾45-80', 'Tbilisi', 41.704825, 44.78857, 'Family-style ordering and familiar dishes (bread, dumplings, grilled meat) make this an easy sell for kids despite the more elevated setting.', true, ARRAY['wine', 'evening']::TEXT[], 12, NULL, NULL)
ON CONFLICT (id) DO NOTHING;

COMMIT;

-- Verification. Expect 10 rows summing to 113, and no region at 0.
SELECT r.sort_order,
       r.id                AS region,
       count(p.id)         AS places
  FROM catalog_regions r
  LEFT JOIN catalog_places p ON p.region_id = r.id
 GROUP BY r.sort_order, r.id
 ORDER BY r.sort_order;

SELECT count(*) AS total_places FROM catalog_places;
